window.POEM_DB=window.POEM_DB||{};POEM_DB["yuan_021"]={"n":"黄溍","dyn":"元","poems":[{"t":"上岩寺访一公","f":"七言律诗","c":["晓色微茫尚带星，修蹊荦确断人行。","独支瘦竹身犹健，高入重云地忽平。","落月正当山缺处，细泉频作雨来声。","上方灯火青林曲，隐隐疏钟一再鸣。"]},{"t":"开元宫","f":"七言律诗","c":["谁使藏舟一夕移，红楼翠幕未全非。","曾闻帝子乘鸾去，疑有仙人化鹤归。","烟径月明瑶草歇，石坛露冷碧桃稀。","赤栏桥畔多时立，閒看杨花作雪飞。"]},{"t":"龙潭山","f":"七言律诗","c":["二月清江照眼明，避风舟楫满回汀。","断云挟雨时时黑，密叶藏花树树青。","习隐未成陶令赋，行歌聊共屈原醒。","碧潭光景无消息，坐看鱼儿点翠萍。"]},{"t":"初至宁海二首 其二","f":"五言律诗","c":["缥缈蛟龙宅，风雷隔杳冥。","人家多面水，岛屿若浮萍。","煮海盐烟黑，淘沙铁气腥。","停骖方问俗，渔唱起前汀。"]},{"t":"初至宁海二首 其一","f":"五言律诗","c":["地至东南尽，城孤邑屡迁。","行山云作路，累石海为田。","蜃炭村村白，棕林树树圆。","桃源名更美，何处有神仙？"]},{"t":"即事","f":"七言律诗","c":["南陌东阡草色齐，愔愔门巷客来稀。","受风燕子轻相逐，著雨杨花湿更飞。","绿树无言春又尽，红尘如雾手频挥。","浮生莽莽吾何计，独立看云竟落晖。"]},{"t":"抱琴","f":"五言律诗","c":["三尺枯桐树，相随年岁深。","此行端有意，何处托知音。","隐隐青山夜，寥寥太古心。","空携水仙曲，更向海中岑。"]},{"t":"独立","f":"七言律诗","c":["数尽飞花一怆然，壮心迢递夕云边。","十年人事空流水，二月风光已杜鹃。","过眼青春宁复得，污人黄土绝堪怜。","故园尚有平生约，可使苍苔到石田。"]},{"t":"夏日漫书","f":"七言律诗","c":["枕上初残柏子香，鸟声帘外已斜阳。","碧山过雨晴逾好，绿树无风晚自凉。","芳岁背人成荏苒，好诗和梦落苍茫。","求羊何不来三径，门掩残书满石床。"]},{"t":"陪仇仁父先生登石头城","f":"五言律诗","c":["谈笑逢诸老，登临失故亭。","薄游成汗漫，高步觉竛竮。","峡水通吴白，淮山入楚青。","平生一杯酒，及此慰飘零。"]},{"t":"寄方韶父先生","f":"五言律诗","c":["牢落《江南赋》，知音寄渺茫。","鹿麋行处有，芝草梦中香。","遥兴沧溟阔，悲歌白发长。","平生今古泪，滴破绿萝裳。"]},{"t":"题观海图","f":"七言律诗","c":["昔年解缆岑江上，初日团团水底红。","鼍吼忽摇千尺浪，鹢飞仍挟半帆风。","遥看岛屿如星散，祇谓神仙有路通。","及此栖身万人海，旧游却在画图中。"]},{"t":"西岘峰","f":"五言古诗","c":["层云抱春岑，急濑泄嵌窦。","修蹊入窈窕，众绿蔚以茂。","名亭标水乐，柱折荒碑仆。","幽寻得缁庐，乱石扶结构。","青精午堪饭，碧涧寒可漱。","平生慕真赏，及此成邂逅。","冥探指绝顶，有路忽通透。","缘萝度蒙密，翠气湿衣袖。","寄身泬寥内，下睨人寰陋。","清讴杂风竹，大啸落岩狖。","东峰在眉睫，可望不可就。","同游却何时，瑶草春已秀。"]},{"t":"阳山昱上人访予吴门寓舍求为湘竹诗予辞以未见竹上人不远六十里自山中舁其竹而来好事有如此者欣然为赋长句","f":"七言古诗","c":["道人来自阳山麓，手携旧种千竿竹。","小裁方斛不盈尺，中有潇湘江一曲。","未信天工能尔奇，不知地脉从谁缩？","晴窗翛翛散烟雾，眼底森然立群玉。","岂期我乃累此君，蒙犯风埃走尘俗。","故山方远重愁绝，新句未成惭迫促。","黄冈之产大中椽，政用材美刳其腹。","愿言保此终天年，岁暮山中伴幽独。"]},{"t":"上京道中杂诗十二首 其六 李老谷","f":"五言古诗","c":["缘崖一径微，入谷双崦窄。","密林日易曛，况及云雨积。","行人望烟火，客舍依山色。","家僮为张灯，野老烦避席。","未觉风俗殊，祇惊关河隔。","严程不可缓，子规勿劝客。"]},{"t":"上京道中杂诗十二首 其七 赤城","f":"五言古诗","c":["鸡鸣秣吾马，晚饭山中行。","何以慰旅怀？","赤城有嘉名。","滩长石齿齿，树细风泠泠。","时见岩壁间，粲若丹砂明。","温泉发其阳，撝诃勤百灵。","前峰指金阁，真境标殊庭。","白道人迹稀，青崖云气生。","信美无少留，缅焉起深情。"]},{"t":"夜兴","f":"五言古诗","c":["秋气入病骨，残梦翛然惊。","芭蕉叶间露，风过皆成声。","揽衣泬寥内，搔首天河横。","饥虫语不休，中宵谁汝令。","孤鸿亦何苦，犯霜度微明。","悠悠念群动，百感忽我并。","大化傥不尔，吾其免营营。"]},{"t":"上京道中杂诗十二首 其十 担子洼","f":"五言古诗","c":["自从始出关，数日走崖谷。","迢迢度偏岭，险尽得平陆。","坡陀皆土山，高下纷起伏。","连天暗丰草，不复见林木。","行人烟际来，牛羊雨中牧。","飒然衣裳单，咫尺异寒燠。","伫立方有怀，相逢仍问俗。","畏途宜疾驱，更傍滦河宿。"]},{"t":"晓行湖上","f":"五言古诗","c":["晓行重湖上，旭日青林半。","雾露寒未除，凫鹥静初散。","夤缘际馀景，闪倏多遗玩。","会心乍有得，抚己还成叹。","夙予丹霞约，久兹芳洲畔。","独往愿易违，离居岁方换。","沙暄芷芽动，春远川华乱。","存期乃寂寞，取适岂烂熳。","小隐傥见招，渔樵共昏旦。"]},{"t":"游西山同项可立宿灵隐西庵","f":"五言古诗","c":["薄游厌人境，振策穷幽躅。","理公所开凿，遗迹在岩麓。","秋杪霜叶丹，石面寒泉绿。","仰窥条上猿，攀萝去相逐。","物情一何适，人事有羁束。","却过猊峰回，遥望松林曲。","前山夜来雨，湿云涨崖谷。","缥缈辨朱甍，禅房带修竹。","故人丹丘彦，抱被能同宿。","名篇聊一咏，异书欣共读。","蹉跎未闻道，黾勉尚干禄。","夙有丘壑期，吾居几时卜。"]},{"t":"题清华亭","f":"五言古诗","c":["名区汇修渚，流望俯平陆。","飞雨天际来，远峰净如沐。","生香馀晚华，繁阴蔼嘉木。","秀色坐可揽，终然不盈掬。","触景幽兴多，接物道机熟。","谁能与之游，食芳饮山渌。"]},{"t":"效古五首 其一","f":"五言律诗","c":["上山见明月，下山月相随。","月岂知爱我，我行自见之。","故山日以远，故人不可思。","殷勤谢明月，愿尔无时亏。"]},{"t":"效古五首 其二","f":"五言古诗","c":["女美众所悦，士穷世所轻。","轻重安足言，泥尽水自清。","淮阴初寄食，曲腰胯下行。","季子黄金多，妻嫂来相迎。","自古已复然，叹息空吞声。"]},{"t":"效古五首 其三","f":"五言律诗","c":["击石乃有火，石火光不扬。","攀天亦有路，天高路何长。","嵯峨万古云，下覆歌哭场。","富贵诚足多，贫贱不可忘。"]},{"t":"效古五首 其四","f":"五言古诗","c":["落花随风吹，各自东西飞。","花飞既不息，水流复无极。","同生不同归，能勿异颜色。","木生则有枝，豹死则有皮。","悠悠岐路间，多言亦奚为。"]},{"t":"效古五首 其五","f":"五言古诗","c":["饮酒莫尽醉，尽醉无馀欢。","读书莫吊古，吊古多悲酸。","萧艾蔽中野，白露摧芳兰。","凤饥不得死，鸱枭食琅玕。","去去复去去，采芝青云端。"]},{"t":"晚晴","f":"五言律诗","c":["泄云散积雨，林水含馀清。","披衣有奇怀，偶从林叟行。","新晴远峰丽，夕阴孤花明。","旷日固所虞，聊兹息营营。"]},{"t":"夜归","f":"五言律诗","c":["空山四寥寥，落日翳榛楚。","蜿蜒草中径，蹑屩度寒雨。","楠杉窈深黑，忽忽疑休虎。","林穷涧水明，稍听归人语。"]},{"t":"陪诸老夜饮","f":"五言古诗","c":["世故不可料，忽若浮云移。","坐令百年内，颠倒殊欢悲。","顾惟我与公，异代同一时。","览古既深慨，抚今亦馀噫。","长川去悠悠，青山莫委蛇。","向来远游意，我行方迟迟。","咄哉有志士，卒岁恒寒饥。","况复托渺茫，欲与千载期。","盈虚信天运，废兴岂人为。","愿公姑舍是，一觞聊可持。"]},{"t":"读忠简宗公遗事","f":"五言古诗","c":["公初起滏阳，艰危属多垒。","苍然国家意，委身干戈里。","阴飙捲翠华，朔雪披南纪。","悠悠虞渊日，力尽挥不止。","寅恭秉斋钺，际会开朱邸。","长安付冯异，汉业中兴始。","宫庭数汛扫，跸路无荆杞。","疚心望銮舆，感激涕如水。","上表方出师，呜呼孔明死。","宴安不可怀，肉食毋乃鄙。","巨舟竟未焚，三语犹在耳。","萧然旧祠下，碧草垂阶戺。","登堂挹光仪，赤舄仍几几。","千载堕泪碑，一夫敢残毁。","传家有遗书，叙事非虚美。","勖哉慎失坠，庶以裨信史。"]},{"t":"陈生诗","f":"五言古诗","c":["陈生少也孤，秉志何轩轩。","读书奉慈母，承颜郁春温。","兀然处膝下，不间晨与昏。","丛丛万井中，陈生深闭门。","晖晖百花时，陈生不窥园。","常恐去左右，或乖覆育恩。","一朝抱长痛，飞霜陨秋萱。","盐酪不入口，日夜涕倾盆。","欲娶弗及养，矢言终不婚。","尚赖百岁后，兄子父所孙。","朝来游子衣，忽逐东风翻。","世方醉糟粕，何庸荐牺尊。","陈生顾谓我，是事安足论。","幸托山水窟，放情咏兰荪。","嗟今学步者，触险争飞奔。","愿尔利锄钁，深斸六籍根。","愿尔进竿橹，高溯百圣源。","源长流自远，根大枝乃蕃。","勿摇崔嵬笔，誇作礧磈言。","弘惟孝与弟，百行兹其元。","咄哉行勿休，日月方沄沄。","赠言岂予敢，情真觉辞繁。","匪为陈生荣，庶感薄俗敦。"]},{"t":"送凌吉叟之杭州教授","f":"五言古诗","c":["浙水西八州，维杭实名都。","古来万人海，逐逐无贤愚。","以兹百年后，淳朴古不如。","翩翩谁家儿，白马骄路隅。","春风樊楼醉，一笑百斛珠。","亦有朱门家，齐讴间吴歈。","绡绮散烟雾，缤纷被僮奴。","可怜彼蚩蚩，久为红尘驱。","颓俗如波澜，孰障群流趋。","又如败屋壁，风雨须人扶。","博士非冗官，岂即无良图。","当令歌舞场，化作弦诵区。","行矣循所务，辞章信其馀。","春风掺别衣，晴沙秀寒芦。","何以赠子行，白云不可呼。","聊持狂者言，用比貂襜褕。"]},{"t":"晚泊钓台下","f":"五言古诗","c":["四山环一水，遗台故巑岏。","那无渔樵居，政复不敢安。","舍舟冲微雨，凭轩俯清湾。","念昔乘兴来，无从寄游观。","今我有行役，乃尔容跻攀。","山灵岂爱我，为解尘土颜。","落日奠蘋藻，清风闻佩环。","幽寻不可极，林暝吾当还。","却去望层碧，孤舟生晚寒。"]},{"t":"重登云黄山","f":"曲","c":["兹山实灵奇，吐纳变舒惨。","太常阙弗录，名号何黭黮。","重华秩山川，盛典轶封䃭。","蒐遗多纶綍，蠲洁罗醢酖。","腐儒世所贷，薄艺守铅椠。","无能旅骏奔，徒取肆游览。","霖潦时始收，天地馀蔼晻。","岚光乍璘㻞，石状终黤黪。","行行恣芒屩，往往得蛙坎。","冒进诚近贪，自画将岂敢。","久之雰埃豁，秀色坐可揽。","青荧插锋锷，翕赩披菡萏。","崖奔马騑騑，石踞虎眈眈。","高寻指天路，幽瞩极玄窞。","前行几台背，后或两髦髧。","缘冈既踸踔，登岭仍?輡。","举头塔庙涌，地平忽如毯。","天人所食息，琼玖化馀糁。","林辉宝灯烧，风语金铎撼。","败壁诗者谁，渍墨乱浓淡。","险尽乃复佳，疲极复何憾。","是节蕤宾初，野荐首昌歜。","煮瀑茶可啜，剖石蜜堪啖。","名谈析毫发，苦语沥肝胆。","理冥心自珍，机凑首屡顉。","阳乌砉西翥，众色齐惨澹。","崔嵬识楩楠，苍莽辨葭菼。","莫投僧所寰，钟镗鼓紞紞。","群居肃不吴，共饭声有嗿。","回睨夸夺场，抚事丛百感。","趋名蛾赴烛，逐利鱼投掺。","何时脱火宅，霍若髭去颔。","绮言息諵諵，妙供纷馣馣。","于焉寄相羊，庶以忘壈坎。","谁云入道苦，馀味需橄榄。"]},{"t":"秋夜观书作","f":"五言古诗","c":["閒居感时驶，独学难为功。","眷言思古人，幽怀极忡忡。","秉烛起中夜，揽卷来清风。","恭惟千载心，皎洁悬无穷。","氓俗自升降，道妙非污隆。","后来亦奚为，黑白纷相攻。","华芳乍可悦，轨辙何由通。","吾将离言说，庶以观其同。","所忧明为累，不惧蓄不丰。","开轩视明河，白月当天中。","怡然掩书坐，夜气方鸿濛。"]},{"t":"览元次山舂陵行有感近事追和其韵以寓鄙怀","f":"五言古诗","c":["惟王始建官，民命有所司。","奈何阅流殍，束手无一施。","属者秋夏交，上状殊酸悲。","赤日纷按行，人马同时疲。","连阡见标榜，不救饥与羸。","仍闻恣鞭箠，惨忉伤肤皮。","检覈须再三，供张常恐迟。","哀哀鬻儿女，贸贸行安之。","感兹欲无诉，既往何由追。","尚惭喔咻恩，稍缓租税期。","云胡有仓卒，徵敛更相随。","但将充其数，肯复计尔赀。","肉食不自鄙，谓我非敢知。","栖栖甔石储，剥割无或遗。","言是邻壤凶，藉此敷恩慈。","宁知是州人，俟死无他为。","出语馀喘息，行步须扶持。","犹令比乐土，疾苦喘谓谁。","俯首州县间，逭责自其宜。","况迫大府令，联络飞符移。","豺狼方在郊，鹰隼宜用时。","区区狝狐兔，政尔何增亏。","吾贱不及议，为君陈苦辞。"]},{"t":"陈孝子诗","f":"五言古诗","c":["南仲杭陈氏，斗龙父所名。","家临百丈溪，父书传考亭。","夫亦人之子，胡独以孝称。","维仲适母盛，王实生宁馨。","盛谓我己出，无殊祝螟蛉。","仲父讳弗言，王卒不自明。","眷然舍之去，呱呱闻泣声。","年运日已往，头角稍峥嵘。","吁天乞陨灭，愿以益父龄。","父没盛亦亡，吊影伤孤茕。","或乃告之故，曰汝王所生。","王居清湖上，去此无十程。","时仲新捧檄，精庐拟横经。","悲号弃其官，肩舆亲奉迎。","安知世代易，人非馀故城。","邻有鹤发妪，叩之久始应。","言我与汝母，少小俱娉婷。","汝母生汝归，去作江东行。","不知今在无，我老犹零仃。","仲也闻益悲，赢粮事晨征。","六年困逆旅，冷雨啼青灯。","譬彼无母雏，投林辄哀鸣。","永丰有施氏，大屋深重扃。","于焉得母处，一夕相合并。","母子更抱持，泪如九河倾。","三日负母还，盗贼方抢攘。","仓黄与之遇，白刃纷交横。","顿首前致辞，覶缕陈衷诚。","能令激高义，相戒勿敢惊。","仲昔以至行，上天降休祯。","灵雁既群集，嘉瓜复冬荣。","区区彼虻蚊，岂遂无人情。","圣人语纯孝，厥有闵与曾。","未闻树奇节，谣颂传轰轰。","此道古或希，此事今可徵。","我歌虽云俚，庶感蚩蚩氓。"]},{"t":"上京道中杂诗十二首 其一 发大都","f":"五言古诗","c":["辞亲独行迈，遥遥抵京国。","胡为突不黔，驱马更远适。","至尊有时巡，树羽殷阡陌。","宿卫必近臣，顾问须耆德。","陋儒亦何知，冗从同执戟。","草深原野青，雨暗关塞黑。","寥寥盛年意，眷眷游子色。","一身万人中，敢不思努力！"]},{"t":"上京道中杂诗十二首 其三 居庸关","f":"五言古诗","c":["连山东北趋，中断忽如凿。","万古争一门，天险不可薄。","圣人大无外，善闭非键钥。","车行已方轨，关吏徒击柝。","居民动成市，庐井互联络。","幽龛白云聚，石磴清泉落。","地虽临要冲，俗乃近淳朴。","政须记桃源，不必铭剑阁。","仆夫跽谓我，无为久淹泊。","山川岂不好，但恐风雨恶。"]},{"t":"上京道中杂诗十二首 其五 枪竿岭","f":"五言古诗","c":["忆昔赐第归，吾母适初度。","蹉跎岁月晚，今辰乃中路。","居人誇具庆，游子惭叱驭。","兹山称最高，扬鞭入烟雾。","矗矗多峭峰，濛濛饶杂树。","崎岖共攀援，踯躅频返顾。","陈情未成表，登高讵能赋！","独怜山下水，远向卢沟去。"]},{"t":"上京道中杂诗十二首 其九 独石","f":"五言古诗","c":["解鞍及亭午，稍欣烟雾收。","苍然众山出，历历如雕锼。","前瞻一石独，灵宫居上头。","颇闻去年夏，水激龙腾湫。","走避登屋山，夜半齐呀咻。","幸兹溪涧中，今作清浅流。","宴安不可怀，变化诚难求。","翠华渺在望，行矣毋淹留。"]},{"t":"上京道中杂诗十二首 其十二 上都分院","f":"五言古诗","c":["晨兴过桓州，旭日生苍凉。","举头见觚棱，金碧何巍煌！","洪河贯其前，青山环四傍。","暮投玉堂署，鳌峰屹中央。","升阶旅群彦，官烛分馀光。","琴册森在侧，谈笑来清觞。","列坐无所为，陈诗咏黄唐。","帝乡岂不乐，父母远莫将。","起视云汉低，垂星烂寒芒。","南飞有冥鸿，邈哉天际翔。"]},{"t":"同王章甫待制校文上京八月十五夜宿龙门驿","f":"五言古诗","c":["凉风堕黄榆，万马皆南驰。","而我方北首，度关及鸣鸡。","石路更幽阻，仆夫惨不怡。","徐驱待明发，泱漭穷烟霏。","貂裘者谁子？","怪我逢掖衣。","为言霜露多，遑遑独安之。","我非不自爱，简书今有期。","忆昔州县间，折腰向小儿。","荏苒二十年，白首初登畿。","同袍如燕鸿，去住恒相违。","悠然慨平生，与世何参差。","暝投龙门驿，高馆临回溪。","青崖拱白月，水木含馀辉。","秋色故潇洒，我行殊未迟。","相从况魁彦，炯若珊瑚枝。","衰暮奚足云，一觞聊共持。"]},{"t":"送王鍊师归四明","f":"五言古诗","c":["飘飘采真侣，乃在四明山。","霞居朝帝所，琼馆留人间。","忽闻双凫舄，却向东南还。","望之若流星，邈然不可攀。","海月照阶戺，天风飞佩环。","我何苦羁旅，冰雪生朱颜。"]},{"t":"湖上即事","f":"五言律诗","c":["垂云昼濛濛，湖面惟一色。","薄暮风更生，际夜雪初积。","凝阴势方盛，尘境喧暂息。","坐久闻挐音，忽然破寥阒。"]},{"t":"登钱山望菰城慨然而赋","f":"五言古诗","c":["吴兴水为州，诸山若浮萍。","况此一培塿，琐屑世未名。","所欣渔樵居，乃与缁锡并。","种竹有万竿，结茅无十楹。","老僧解人意，踪履能相迎。","芳草被行径，朱藤暗岩扃。","萧条空阶暮，日照莓苔青。","犹嫌所历卑，未极游眺情。","耸身白云上，始见春申城。","想当高会时，楼观飞青冥。","竭海荐罍勺，穷山羞鼎铏。","安知千载后，寂寞无人行。","煌煌冠盖区，壤壤狐兔茔。","归来朱门客，听此松风声。"]},{"t":"雪窦纪游四首 其一","f":"五言古诗","c":["高人欣相迎，山门带流水。","风生珠树间，月窥镜池里。","触景遂成迷，应接殊未已。"]},{"t":"雪窦纪游四首 其二","f":"五言古诗","c":["幽寻指山椒，崖倾忽如泻。","俯身视木末，悬水在足下。","冥冥岩岫中，宴坐奚为者。"]},{"t":"雪窦纪游四首 其三","f":"五言古诗","c":["诘旦逾西冈，草木益深秀。","梯苔下绝巘，坐石看飞溜。","阴灵多窟宅，欲往不敢又。"]},{"t":"雪窦纪游四首 其四","f":"五言古诗","c":["兴移初出山，系缆长汀树。","夜来雪已深，溪风水难度。","犹疑钟磬音，遥遥白雪处。"]},{"t":"可怜行","f":"七言古诗","c":["红颜白面可怜子，杖藜饥走荒山里。","翠眉新妇雪色儿，掩袖娇啼瘦如鬼。","道傍朱门照霜戟，肠断汝翁呼不起。","金鱼象笏供樗蒱，纨裤终然愁饿死。","春风秋月哀思多，嗟汝少年奈老何。"]},{"t":"昆崙歌寄吾丘子行","f":"楚辞体","c":["翠鸾啼云天四垂，花龙双双神姥归。","金仙忆君泪如水，昌阳落花青蕊蕊。","层城珠阙扬素氛，开明狺狺环九门。","羲和走马不待人，鲸鱼吸海海生尘。","若有人兮怅修阻，紫玉参差老凤语。","笑挥如意教云舞，云间鹤雏生两羽。","归来归来勿蹉跎，秋风吹折玕琪柯。"]},{"t":"金华山赠同游者三十韵","f":"七言古诗","c":["杖藜初出城西门，万株红叶如云屯。","芙蓉峰前问行路，宛宛一线随潺湲。","水声渐远山渐近，弱萝纤葛手所扪。","须臾横侧变峰岭，高岸忽复为平原。","细泉浏浏竹竿直，石树骈立疑同根。","剥金败碧逢废刹，犹以第一名其轩。","天明独去吊遗迹，玉女委蜕空丘墦。","楼居西起望明灭，石扉呀若山之樊。","罅幽穴险径沮洳，膝行匍匐不得奔。","剨观崖广架寥泬，双龙绕霤蟠蜿蜿。","纷纶怪状满岩腹，熊虎踞伏鸾凤骞。","其馀琐细无不有，形求象索难具言。","前趋林麓却下缒，俯瞩九地穷涯垠。","青枝翠羽不复辨，但听风水声喧喧。","高烧松炬度其背，珠箔忽随华灯繁。","耸身上出指绝顶，碧桐高下弥山园。","遥穿蓬艾蹋云雨，险艰从此不易论。","秋毫细路莫容足，下瞰不测傍无藩。","怪藤如钩草如剑，举首仰叹愁攀援。","山翁顾之笑引臂，前牵后接猴与猿。","驰坑跨谷攲侧过，背汗喘息逾炰燔。","阴沈古洞閟星日，虽有寒暑无朝昏。","却行左转复深入，愈觉憀慄摇心魂。","珠缨缥缈现满月，稽首大士天人尊。","拂衣径逐飞鸟下，青山出没波涛翻。","或云汉人隐身处，彷佛肩背馀苔痕。","蛇蟠磬折又数里，龛岩十丈开墉垣。","夜归草堂殿突兀，坐看云月吐复吞。","怡然携手尽文士，颇觉笔下来源源。","名山石室如可托，幸子岁晏来无谖。"]},{"t":"题李坦之诗卷","f":"七言古诗","c":["神仙中人世莫识，政以文章为戏剧。","李生也复可怜人，手种蟠桃待春色。","山空岁寒谁念汝，青枫堕影霜露白。","远游赋成一朝去，翠盖云旗暮何适。","蓬莱烟雾秋冥冥，邓君白鹿无消息。","袖中骊珠三百颗，夜深勿近蛟龙宅。","金华之山青矗天，山人看山忘岁年。","黄精芝草幸可食，安得与子巢其间。","石床醉听松风眠，无为长歌怨如哭，使汝恻怆凋朱颜。"]},{"t":"苕溪风雨中章德茂同泛","f":"七言古诗","c":["黑风翻江白雨倾，樯攲柁侧断人行。","此时惟我与章子，孤舟荡漾烟波里。","蒹葭苍苍杨柳黄，浩歌击舷兴弥长。","翩然一叶恣掀舞，青山白塔频低昂。","朝过城南暮城北，舟人问我将谁适。","章子掉头作吴语，秋水夜来深几许。","忽看大字标竹林，寺门对水仍阴阴。","敲门见竹不见人，竹间翠石何萧森。","回舟少林雨如注，四顾冥茫但烟雾。","鱼惊龙跃吾不知，披蓑却入菰蒲去。","岸傍群儿拍手呼，笑言狂客世所无。","呜呼古人今则无，后来视我知何如！","为君留此有声画，题作扁舟烟雨图。"]},{"t":"杭州送儿侄归里","f":"七言古诗","c":["空江月满潮声怒，二儿勇踏潮头去。","故园天末眇予怀，梦中识汝归时路。","起向江楼遥望汝，江上青枫正霜露。","凉风飒飒吹汝急，橹摇背指龙山渡。","翩然一叶舞中流，嗟汝童心得无惧。","自我西游历三纪，举目交朋半新故。","下车相揖何纷纷，白头朝士犹徒步。","玄都观里旧桃花，见我重来能几度。","缅思畴昔仍念汝，徙倚阑干日将暮。","前潮将断后潮续，层波复浪无重数。","鱼龙出没相后先，疾雷槌山雨如注。","隔岸峰峦空复多，沙际冥茫但烟雾。","计程知汝已登陆，息肩弛担今何处？","明朝过我三釜山，能勿徘徊起哀慕。","近闻旱魃肆为虐，杀吾手植千株树。","且须为我语比邻，莫遣牛羊上丘墓。"]},{"t":"番阳周节士歌","f":"七言古诗","c":["周君生长番君里，长身俣俣须仍美。","师张先生业孔氏，夏萤冬雪频继晷。","先生爱君不骫骳，君谓先生我知己。","遭时战伐多疮痏，贼众乘之作奸宄。","郡檄先生俾一洗，先生慷慨为之起。","曰彼蚩蚩聚蜂蚁，凶渠本我家奴尔。","我将笞之用折箠，披其角毛脱距觜。","奴挟兵来速如鬼，反噬其主先生死。","先生诸子俱幼稚，周君闻之失箸匕。","曰古复雠盖有礼，师长之雠视兄弟。","我今必也书于士，走告郡府伏以俟。","府公义之弗敢止，授以殳斨与弧矢。","或云彼众我无几，盍募援兵为表里。","君奋不顾行益驶，贾勇直前无与比。","贼穷掷金计何诡，得金失贼堕其饵。","亟取贪夫尸诸市，士气复振贼乃靡。","追奔逐北劘贼垒，迅雷不及掩其耳。","一栅既覆众栅毁，生致贼奴洎妻子。","刌其心肺献俎几，告于先生辞亹亹。","凯旋公庭旗旖旎，散遣部伍归耘耔。","天戈耀日方南指，郡将效死弗拜跪。","周君堂堂众所恃，人咸谓君今可仕。","细书降表仅尺纸，大哉公侯小刺史。","君言我本不获已，出为吾师刷雠耻。","罪人已得贼已弭，东村西落无荆杞。","不义富贵宁饮水，公毋多谈且休矣。","闭门高卧肉生髀，白驹空谷馀四纪。","殁葬金潭有庙祀，乡人岁时击羊豕。","子暾来与冑子齿，踵门涕泣言如此。","嗟君壮节甚奇伟，播兹歌诗侑哀诔。"]},{"t":"题醉歌图","f":"七言古诗","c":["翰林主人天上来，布帆不为鲈鱼开。","江湖渺渺天一色，朝光暮霭相徘徊。","昔贤心赏馀胜处，但有水竹无亭台。","碑材久已没荆棘，屐齿不复留莓苔。","后来视今犹视昔，今我不乐何为哉。","大官马湩远莫致，邻翁绿蚁浮新醅。","欣然一饮便终夕，鼻端气息如云雷。","是间别有一天地，不知何处为蓬莱？","回观方内海一粟，醯鸡尘瓮何喧豗。","黄冠秘监太狂态，骑鲸供奉非仙才。","挥毫《政要》真学士，锋车流水行相催。","瑶池曲宴多雨露，归欤酌彼黄金罍。"]},{"t":"雨二首 其一","f":"五言律诗","c":["兀坐九十日，雨声殊未收。","花时翻益睡，茅屋不禁愁。","生事吾何望，春寒晚故留。","江波青满眼，万里付双鸥。"]},{"t":"雨二首 其二","f":"五言律诗","c":["泥潦今如此，出门知路难。","蓬蒿春自长，桃李梦曾看。","未觉龙公倦，谁怜燕子寒？","青灯耿萧瑟，千载入忧端。"]},{"t":"寄友人","f":"五言律诗","c":["怜君山水意，局促守柴扉。","故里悲秋草，凉风满褐衣。","沧洲斜日晚，白社几人归。","寂寞分遥念，天寒木叶稀。"]},{"t":"秋怀二首 其一","f":"五言律诗","c":["天末云犹去，山中岁欲徂。","周流吾道在，叹息古人无。","野鹊疑秋树，新驹怯暝途。","苍茫念同志，微薄忝为儒。"]},{"t":"秋怀二首 其二","f":"五言律诗","c":["稍稍秋河落，娟娟宿露微。","天清江不息，野迥树相依。","回首狂歌数，惊心昨梦非。","流萤无思极，巧入绛帷飞。"]},{"t":"凭轩","f":"五言律诗","c":["信有儒冠误，凭轩意欲迷。","山深风雨恶，天阔羽毛低。","他日开炎瘴，连城送鼓鼙。","荷殳吾愧尔，未敢叹涂泥。"]},{"t":"风雨","f":"五言律诗","c":["风雨忽如此，闭门方昼眠。","故应为计拙，可复要人怜。","灯火羌村路，桑麻杜曲田。","悠悠今视昔，把卷一茫然。"]},{"t":"社日重过方子践","f":"五言律诗","c":["东风吹客衣，长忆见君时。","一别惊云散，重来与燕期。","春深今雨夕，花老去年枝。","莫待空山里，青灯有所思。"]},{"t":"闻子践卧疾","f":"五言律诗","c":["吾子仍多病，何人共解颜。","水声和药臼，春色闭松关。","积雨连三月，怀人剧万山。","同游况零落，浩荡可追攀。"]},{"t":"过谢皋羽墓","f":"五言律诗","c":["识子今无日，风流可复寻。","山林馀楚制，弟子解闽音。","沧海他年梦，青天后夜心。","平生匣中剑，零落遂如今。"]},{"t":"八咏楼","f":"五言律诗","c":["怀古荒碑在，登楼晚望赊。","秋阴垂野薄，江势抱城斜。","天地悲游子，冰霜感岁华。","红尘吹裋褐，归兴及清笳。"]},{"t":"明月楼","f":"五言律诗","c":["遗堞何年有，飞甍压上头。","鼓鼙分大幕，香火望灵湫。","曲岸舟如失，遥沙树欲浮。","登临且吾土，未敢恨淹留。"]},{"t":"杭州寄子践","f":"五言律诗","c":["樽酒何人共，春光著处同。","乾坤容野马，岁月失飞鸿。","俗眼能无白，风花故自红。","向来常处士，早已负诸公。"]},{"t":"次韵答子践","f":"五言律诗","c":["不谓飞霞佩，珊然寂寞滨。","相看今雨夕，渐近长年人。","往事惊如梦，何峰拟卜邻。","平生千里驾，还往得辞频。"]},{"t":"次韵答陈君采兼简一二同志二首 其一","f":"五言律诗","c":["默守知存道，清言不废儒。","身方同木石，名已在江湖。","此士须前席，何人属后车？","唯应耕钓者，缥缈识霞裾。"]},{"t":"次韵答陈君采兼简一二同志二首 其二","f":"五言律诗","c":["尚想南归始，簪花出禁闱。","尘沙迷故步，桃李借馀辉。","有日酬天造，终身返布衣。","风流成二老，巾屦傥相依。"]},{"t":"送陈养直归四明","f":"五言律诗","c":["迢迢浙河水，同渡不同归。","执袂方成别，惊帆已若飞。","野桥行处酒，风雪去时衣。","瞻望嗟何及，天长鸿雁微。"]},{"t":"送赵宗吉御史","f":"五言律诗","c":["忆共趋龙禁，惊闻正豸冠。","汗颜居馆下，矫首望云端。","去路黄河直，飞霜白日寒。","仙舟如可托，归理钓鱼竿。"]},{"t":"过永康桃岩","f":"五言律诗","c":["立石平如削，飞云近可梯。","莫穷千古胜，但惜众山低。","灵草经春长，珍禽隔树啼。","人言旧朝士，感事有留题。"]},{"t":"九日登石头城","f":"五言古诗","c":["背郭嚣尘远，高秋川岳清。","幽怀初旷荡，陈迹故纵横。","遥望龙盘旧，长怜蚁穴争。","绀园随处辟，粉堞向来倾。","发草窥眢井，看碑验故茔。","门开苍耳路，亭爱翠微名。","远树淮南出，沧江鸟外明。","人烟川浩渺，风物岁峥嵘。","吹帽仍佳节，传觞但老兵。","愚生杂蛙黾，浪走愧璜珩。","去去帆樯尽，萧萧芦苇鸣。","登高未成赋，览古独含情。","政复哀王粲，何堪厌祢衡。","敝庐沧海曲，目断白云生。"]},{"t":"同刘遂初修撰周伯温编修任大瞻经历王继志架阁西山行香次遂初韵","f":"五言古诗","c":["仙驭宾天久，衣冠出此游。","祗园金地古，汾水白云秋。","谒拜陪诸彦，跻攀展寸眸。","始知山水窟，近在帝王州。","深岫藏青霭，平芜映绿畴。","层台临太液，环海象瀛洲。","粤自遗弓剑，无从望黈旒。","明庭虚次舍，綵缆旧维舟。","陛戟盈千列，灵舆副九斿。","祠官侦伺谨，中使往来稠。","备礼兼今昔，求神遍显幽。","琅函开贝叶，玉瓒荐黄流。","肸蚃人天合，辉光日月侔。","遥看陈羽卫，疑是问龙楼。","花雨缤纷落，香烟泱漭浮。","重关罗虎兕，簇仗拥螭虬。","去去箫声远，微微扇影收。","清都成梦境，尘劫等浮沤。","归径缘湖尾，残阳挂树头。","举杯相慰藉，分席暂淹留。","物色迓行辔，风寒袭敝裘。","回瞻天路永，坐感岁时周。","恋阙惭衰朽，非材堕谬悠。","词休富鸿藻，珍赠若为酬。"]},{"t":"试院同诸公为主试官作","f":"五言古诗","c":["右辖升庸日，秋闱献艺初。","端居烦坐镇，妙简备贤书。","忆昔兴文运，惟天启圣谟。","教条行九有，学业出三馀。","儒术俄中否，词场遂久虚。","纶言何噩噩，髦士共于于。","吐握承谦德，飞扬感壮图。","至公留藻鉴，成物待洪炉。","肃穆华星聚，涵容化日舒。","谁欤随计吏，行矣听传胪。","橘柚天庭贡，参苓相府储。","铺张须钜笔，衰朽愧荒疏。"]},{"t":"凤凰山","f":"七言律诗","c":["沧海桑田事渺茫，行逢遗老色凄凉。","为言故国游麋鹿，漫指空山号凤凰。","春尽绿莎迷辇道，雨多苍荠上宫墙。","遥知汴水东流畔，更有平芜与夕阳。"]},{"t":"早起","f":"七言律诗","c":["漠漠晴檐散薄云，独搔短发立清晨。","春风入树无行迹，晓月窥帘欲近人。","旋觉新吟随梦寐，不知清露湿衣巾。","何人正踏长安陌，想见看花拂面尘。"]},{"t":"予与刘君师鲁为文字交十有四年而固未尝相识也兹过武林偶遂良觌有喜而赋","f":"七言律诗","c":["邂逅神交十载馀，青枫落月几愁予。","何言此日同倾盖，胜读平生未见书。","天上玉堂容可到，山中金匮得长虚。","故多馀事宜商略，可待秋风怨索居。"]},{"t":"次韵山南先生遣兴","f":"七言律诗","c":["稍觉春风入剪裁，更无魂梦到尘埃。","苔枝自送黄昏影，宝篆频销白昼灰。","世态渐应随日别，老怀可复向人开。","拥炉坐听萧萧雪，载酒携琴暮也来。"]},{"t":"寄朱仲山","f":"七言律诗","c":["异县关心朔雁飞，酒灯棋雨计频违。","寄书全觉嵇康懒，入梦多疑李白非。","黄叶闭门方寂寂，碧云回首故依依。","相逢赖有梅花约，试蹋东风走翠微。"]},{"t":"逢叶伯几","f":"七言律诗","c":["水烟沙雨送归航，枫叶芦花已十霜。","瑶曲天风春梦远，墨池秋草故游荒。","碧峰又是新回雁，白石依然旧化羊。","一笑相逢却成别，暮云千里思茫茫。"]},{"t":"宿贾氏山房","f":"七言律诗","c":["暝色苍茫赴远岑，独追灯火下荒浔。","寒沙细水通幽径，修竹高楠走翠阴。","草草悲欢中夜语，悠悠醉醒百年心。","石霜烟月寒无寐，坐听疏钟出二林。"]},{"t":"过乌伤墓","f":"七言律诗","c":["丹青像设始何年，翁仲遗墟自古传。","时有北人来下马，不知秦树几啼鹃。","牧童解指看碑路，野衲分耕祭墓田。","回首长安西日外，茂陵松柏正苍烟。"]},{"t":"金陵天津桥","f":"七言律诗","c":["五云零落渺天涯，陈迹苍茫日自斜。","画角已吹边塞曲，红蓝新长内园花。","可怜遗老埋黄壤，曾倚春风望翠华。","好在北山猿与鹤，依然同住旧烟霞。"]},{"t":"送人归豫章","f":"七言律诗","c":["已觉栖迟懒曳裾，可能为我强踌躇。","一帆秋色红尘外，千里江关白雁初。","建业水清谁共饮？","浔阳潮断定无书。","黄金未尽朱颜在，莫种桃花学隐居。"]},{"t":"送韶父先生游京口","f":"七言律诗","c":["不到南徐三十春，好将梦寐吊遗民。","也知往事如流水，祇想重来是后身。","棹响官河风色暮，云离野服鬓毛新。","旧游偶失扶桑路，烦向沧江一问津。"]},{"t":"寄张如心","f":"七言律诗","c":["谬羡侏儒饱一囊，旧游搔首独凄凉。","连天断雁初沈日，匝地寒花欲有霜。","闻道为郎须白发，未殊高枕待黄粱。","红颜好在张公子，坐听松风春昼长。"]},{"t":"余山","f":"七言律诗","c":["春云牢落雁无声，沙岸参差石有棱。","双屐漫穷芳草径，一龛长愧白头僧。","晴涛闪闪翻孤日，山木昏昏卷翠藤。","后夜清风满遥念，梦游空指上方灯。"]},{"t":"次韵方子践观潮","f":"七言律诗","c":["潮生潮落有时休，朝暮吴儿几白头。","被发祗誇迎骇浪，侧身宁解障奔流。","江吹碧瓦人声晓，云闪朱旗海气秋。","后夜月明天在水，有谁能此试登楼？"]},{"t":"次韵答蒋春卿","f":"七言律诗","c":["不谓红尘拂面时，轩然谈笑一舒眉。","晴风石鼎浮花乳，夜雨春盘冷碧丝。","握手遽成三宿恋，论心那觉十年迟。","酒船渔网归无计，未必山前白鹭知。"]},{"t":"重游毗山","f":"七言律诗","c":["十载重来思惘然，胜游邂逅一开颜。","高林有色烟云净，曲径无香草树閒。","漫遣金樽催白日，绝怜红粉涴青山。","南朝旧迹今谁记，肠断风流不可攀。"]},{"t":"花信","f":"七言律诗","c":["已觉寻芳去较迟，千林红紫总纷披。","几经夜雨能无恙，试问春风竟不知。","斜日游蜂应有梦，野亭立马已多时。","殷勤却是江南客，曾擘冰霜寄一枝。"]},{"t":"北山归路呈古心师兼简方外诸友","f":"七言律诗","c":["寻幽偶向灵源宿，却过云关望翠微。","初日映空千树立，惊风绕涧百泉飞。","旧题岁月人频异，乍别烟霞路易非。","幸有潘郎遗事在，何时一钵去如归。"]},{"t":"陈山晚泊","f":"七言律诗","c":["一柱孤撑杳霭间，人言此是客星山。","风流百世今谁嗣，应诏诸生故未还。","荒冢草深迂石路，高斋月满閟松关。","穷年漫迹沧江上，及此维舟独厚颜。"]},{"t":"湖心寺夜坐","f":"七言律诗","c":["萧萧凉月满池台，水槛风棂四面开。","一炷残灯何熠煜，半檐衰柳故崔嵬。","谬持微禄知无补，未谢馀缘得重来。","尘土马蹄何日事，可容良夜废衔杯。"]},{"t":"题金明宴游图","f":"七言律诗","c":["危楼缥缈碧波中，曲槛方棂面面通。","云气傍花如欲雨，柳丝垂地不惊风。","千年华表人非是，九奏钧天乐未终。","更有残山并剩水，烦君回首六桥东。"]},{"t":"题雪窦妙高台","f":"七言律诗","c":["偶为清游宿梵宫，凌晨试上最高峰。","水翻雪色寒犹落，云掩丹光远更重。","旧有一僧能跨虎，近闻三洞尽藏龙。","下方车马应难到，烟际惟听日暮钟。"]},{"t":"送叶仲舆巡检","f":"七言律诗","c":["重著儒冠望帝乡，翩然一舸犯晨霜。","秋来鬓发依前黑，日射河流彻底黄。","此去乘槎须有路，可容执戟更为郎。","丝纶阁下多知己，握手应分满袖香。"]},{"t":"送赵继清潮州推官","f":"七言律诗","c":["相国南迁有故居，理官高选出新除。","承恩特与金鱼袋，访旧争迎驷马车。","春入圜扉庭草暗，天低驿路岭梅疏。","凤池不隔同年面，归及梅花雁影初。"]},{"t":"送龙南欧阳县尹","f":"七言律诗","c":["丝纶阁下半同袍，独上南船去莫招。","出宰不嫌官俸薄，过家未觉驿程遥。","长溪白石睛雷转，深洞黄茅毒雾消。","想见行春有佳句，坐令远俗变风谣。"]},{"t":"赠黄资深","f":"七言律诗","c":["凉风萧萧吹敝裘，三年小作周南留。","相逢倾盖尽青眼，肯抱遗经空白头。","捧檄定知毛义喜，著书非有虞卿愁。","春秋决事待公等，莫恋寒毡成久游。"]},{"t":"送陈季和","f":"七言律诗","c":["高斋灯火正萧条，忽溯天风上泬寥。","共喜弹冠如贡禹，岂期投笔学班超。","时清桴鼓元无用，岁晚弓旌傥见招。","雪后江南春水活，重来莫厌驿程遥。"]},{"t":"送张良卿学士之淮南","f":"七言律诗","c":["坐厌流尘拂面红，行携凉月下青空。","三千里外扬州鹤，四十年前御史骢。","先庙铁衣犹挂壁，儿郎玉帐已生风。","贞元朝士今无几，归及花时一笑同。"]},{"t":"题莫氏山庄图","f":"七言律诗","c":["施移小隐傍南峰，远有咸平处士风。","山态近人犹偃蹇，湖光无雨亦空濛。","行春杖屦时时到，临水轩窗面面通。","别作新亭供戏剧，青帘遥曳杏花中。"]},{"t":"予与江阴何鼎叔铉别三十六年乃相见于钱唐感旧述情谩成四韵","f":"七言律诗","c":["月寒霜树久相依，春去风花各自飞。","远信已随潮水断，故交浑若晓星稀。","绨袍可恋知谁在，青镜频看叹昨非。","正欲从君共倾倒，莫言兴尽便须归。"]},{"t":"送内史府孙知事还京","f":"七言律诗","c":["春风朱邸雪初消，野宿貔貅静不骄。","绿水芙蓉分上幕，青云騕袅度轻轺。","龙庭会祭包茅贡，豹尾宸居佩玉朝。","下土微臣今老矣，淹留敢望小山招。"]},{"t":"感旧","f":"七言律诗","c":["华屋山丘不可期，岘峰依旧绿参差。","空怀下榻延徐孺，无复乘舟访戴逵。","日暮更闻邻舍笛，岁寒赖有角弓诗。","旧游寂寞成今古，冷石秋花处处悲。"]},{"t":"答友人","f":"七言律诗","c":["芝掌峰前一杯酒，别离岁晚递相望。","野梅如雪遥入眼，晓雁连天寒叫霜。","闭门穷巷灯火冷，回首苍山云树长。","几时抱被却同宿，愧尔诗筒远送将。"]},{"t":"山中偶题","f":"五言绝句","c":["古苔隐石色，寒花明药丛。","有时白涧雨，终日青松风。"]},{"t":"夜坐","f":"五言绝句","c":["凉风动千里，孤坐思沧洲。","白露洗明月，青天此夜秋。"]},{"t":"金陵客中送友人归里","f":"七言绝句","c":["青阳河畔杜鹃啼，归路如烟定不迷。","应到故山丛桂里，笑人骑马听朝鸡。"]},{"t":"有感二首 其一","f":"七言绝句","c":["橘柚青黄照眼垂，秋风篱落自纷披。","颇闻玉食登蛮果，不独涪州有荔枝。"]},{"t":"有感二首 其二","f":"七言绝句","c":["汉室需材拔隐沦，贩缯屠狗各求伸。","可怜风雪南山下，别有当年射虎人。"]},{"t":"叶审言张子长同游北山智者寺既归复与子长至赤松由小桃源登炼子山谒二皇君祠回宿宝积观赋绝句十首 其一","f":"七言绝句","c":["天风吹我度峥嵘，春著千峦蓊蓊青。","紫陌红尘宁有此，十年空负北山灵。"]},{"t":"叶审言张子长同游北山智者寺既归复与子长至赤松由小桃源登炼子山谒二皇君祠回宿宝积观赋绝句十首 其二","f":"七言绝句","c":["芙蓉峰下南朝寺，水秀山明两绝奇。","更向水穷山尽处，一庵高贮碧云师。"]},{"t":"叶审言张子长同游北山智者寺既归复与子长至赤松由小桃源登炼子山谒二皇君祠回宿宝积观赋绝句十首 其三","f":"七言绝句","c":["却问仙山去几程，白云如簇近相迎。","直须不脱登山屐，行尽松声与水声。"]},{"t":"叶审言张子长同游北山智者寺既归复与子长至赤松由小桃源登炼子山谒二皇君祠回宿宝积观赋绝句十首 其四","f":"七言绝句","c":["山中今是太平民，尚与人间隔几尘。","流水桃花三百曲，莫教重误武陵人。"]},{"t":"叶审言张子长同游北山智者寺既归复与子长至赤松由小桃源登炼子山谒二皇君祠回宿宝积观赋绝句十首 其五","f":"七言绝句","c":["偶看飞花逐水红，不知身过乱云东。","回头旋觉峰峦别，惟有青天面面同。"]},{"t":"叶审言张子长同游北山智者寺既归复与子长至赤松由小桃源登炼子山谒二皇君祠回宿宝积观赋绝句十首 其六","f":"七言绝句","c":["双鹤冲天岁月多，至今香火压嵯峨。","刘郎不是无兄弟，奈此丹鸡白犬何。"]},{"t":"叶审言张子长同游北山智者寺既归复与子长至赤松由小桃源登炼子山谒二皇君祠回宿宝积观赋绝句十首 其七","f":"七言绝句","c":["坐爱春泉响翠微，玉花吹湿薜萝衣。","何人为擘冰壶破，共看青天白练飞。"]},{"t":"叶审言张子长同游北山智者寺既归复与子长至赤松由小桃源登炼子山谒二皇君祠回宿宝积观赋绝句十首 其八","f":"七言绝句","c":["削立城心双白塔，几疑日月费撑支。","一朝顿在阑干底，始悟从来见处卑。"]},{"t":"叶审言张子长同游北山智者寺既归复与子长至赤松由小桃源登炼子山谒二皇君祠回宿宝积观赋绝句十首 其九","f":"七言绝句","c":["遥忆仙华鹤发翁，清泉白石满奇胸。","若为此日千峰顶，更试平生九节筇。"]},{"t":"叶审言张子长同游北山智者寺既归复与子长至赤松由小桃源登炼子山谒二皇君祠回宿宝积观赋绝句十首 其十","f":"七言绝句","c":["一宿山中竟莫留，可能长伴赤松游。","殷勤好去张公子，休爱人间万户侯。"]},{"t":"次韵章兄雨中","f":"七言绝句","c":["春尽馀寒去却回，江天五月未闻雷。","南风祗在浮云外，弹折朱弦唤不来。"]},{"t":"松江舟中偶书","f":"七言绝句","c":["移舟夜泊华亭县，却听吴歌思眇然。","最忆淀山湖北寺，白云堆里看青天。"]},{"t":"青山白云图","f":"七言绝句","c":["十年失脚走红尘，忘却山中有白云。","忽见画图疑是梦，冷花凉叶思纷纷。"]},{"t":"桃竹画眉图","f":"七言绝句","c":["说尽春愁貌不成，翠深红远若为情。","江南有客头空白，肠断东风百啭声。"]},{"t":"追和景传新店客舍壁间韵","f":"七言绝句","c":["我梦方酣子遽醒，绝弦可复要人听。","梨花寒食东风恶，泪尽重山宿草青。"]},{"t":"滦阳邢君隐于药制芍药芽代茗饮号曰琼芽先朝尝以进御云 其一","f":"七言绝句","c":["芳苗簇簇遍山阿，玉蕾珠芽未足多。","千载《茶经》有遗恨，吴侬元不过滦河。"]},{"t":"滦阳邢君隐于药制芍药芽代茗饮号曰琼芽先朝尝以进御云 其二","f":"七言绝句","c":["春风北苑斗时新，万里函封效贡珍。","羡尔托根天尺五，不劳飞骑走红尘。"]},{"t":"次韵虞学士上京道中","f":"七言绝句","c":["欲去仍为一日留，玉堂中夜有词头。","归鞍晓逐南飞雁，犹及西山半夜秋。"]},{"t":"水仙图","f":"七言绝句","c":["翛翛翠羽映鸣珰，谁遣乘风过我傍？","岁晏高堂空四壁，一帘烟雨梦潇湘。"]},{"t":"山水图","f":"七言绝句","c":["老树无阴石有棱，乱山高下白云层。","梦中犹识江南路，惟恨舟人唤不应。"]},{"t":"海月图","f":"七言绝句","c":["忆曾夜叩潮音洞，海阔天高月正中。","坐对画图如梦寐，六街尘土昼濛濛。"]},{"t":"瑶池春宴图","f":"七言绝句","c":["西飞青雀几时还，贝阙琳宫缥缈间。","笔底春风殊未老，蟠桃积核已如山。"]},{"t":"东阳县西道中","f":"七言绝句","c":["柿叶成阴绿满村，桐花覆地草连云。","百年旧事无人记，犹指前朝御史坟。"]},{"t":"寒食舟中","f":"七言绝句","c":["东风溪水碧涟涟，溪上青萝独系船。","正是落花寒食夜，水烟沙月又鸣鹃。"]},{"t":"哭御史王公二首 其一","f":"七言绝句","c":["掉头东下苦匆匆，径挟群仙入贝宫。","眼底珊瑚高百尺，钓竿吹折一丝风。"]},{"t":"哭御史王公二首 其二","f":"七言绝句","c":["胶液中流事可叹，海云飞雨失青天。","陆郎地下惊相见，应讶来迟二十年。"]},{"t":"陶学士驿舍图","f":"七言绝句","c":["一笑相逢亦偶然，浪将恩怨向人传。","无端更被丹青污，狼藉春风数百年。"]},{"t":"宣和画木石","f":"七言绝句","c":["石边古木尚青枝，地老天荒石不知。","故国小臣谁在者？","苍梧落照不成悲。"]},{"t":"题高公画竹石","f":"七言绝句","c":["木叶萧萧半欲空，竹竿袅袅不成丛。","绝怜意匠经营处，都在风烟惨淡中。"]},{"t":"题金德原所藏元晖小景","f":"七言绝句","c":["床头书画正纵横，忽值今朝醉眼醒。","起向米家船上看，云山元是旧时青。"]},{"t":"四皓围棋图","f":"七言绝句","c":["当局沈吟只谩劳，区区胜败直秋毫。","颠嬴蹶项非君事，赖有安刘末著高。"]},{"t":"集渊明句题李中甫员外稼亭","f":"五言古诗","c":["东方有一士，客养千金躯。","束带听鸣鸡，出则陪文舆。","代耕本非望，暂与田园疏。","田园日梦想，投冠旋旧墟。","兴言在兹春，新畴复应畬。","田父有好怀，过门更相呼。","披草共来往，履历周故居。","悠悠待秋稼，时还读我书。","虽未量岁功，栖迟固多娱。","此事真复乐，此语真不虚。","饯送倾皇朝，归子念前涂。","前涂当几许，直至东海隅。","古时功名士，事事在中都。","遥遥沮溺心，君情定何如。"]},{"t":"集渊明句题胡主簿嘉树轩","f":"五言古诗","c":["孟夏草木长，霜露憔悴之。","蔼蔼堂前林，冬夏常如兹。","严霜九月中，卓然见高枝。","如何舍此去，白日掩荆扉。","深谷久应芜，此荫独不衰。","黾勉六九年，怀此贞秀姿。","常恐负此怀，未足为高栖。","及时当勉励，慷慨思南归。","亲戚共一处，日夕欢相持。","披榛步荒墟，登高赋新诗。","坐止高荫下，一觞聊可挥。","从今至岁寒，纵心复何疑。"]},{"t":"永嘉王君自制挽歌词盖能安死生而未忘情乎死生者也集渊明句以释之","f":"五言古诗","c":["自古皆有没，我今始知之。","居常待其尽，逝将不复疑。","人生无根蒂，去来何依依。","既来孰不去，奄去靡归期。","复得返自然，人间良可辞。","何事空立言，念此怀悲栖。","日醉或能忘，一觞聊可挥。","且极今朝乐，千载非所知。"]},{"t":"钟山","f":"曲","c":["平陆漫千里，兹山乃穹然。","犹怜布金地，未即辞喧阗。","岩液散珠琲，春冈走蜿蜒。","稍欣陟幽遂，登顿衣屡褰。","路细石??，崖深竹娟娟。","洞扉剨开敞，峻峰指中天。","冥探历嵚崟，垂萝弱容牵。","碧潭隐光怪，华雨漂崇筵。","下睨飞鸟辈，茫茫但苍烟。","眇然玄圃期，凄凉云峤篇。","休驾将未能，惆怅春风前。"]},{"t":"敬亭山","f":"五言古诗","c":["昔窥敬亭作，今陟裴公寺。","徵素非始游，赏胜资深诣。","翛翛缘水木，宛宛交蹊术。","绿缛涧草丰，幽飗松飙驶。","微钟响沓嶂，高阁浮花气。","聿薰栴檀妙，岂爱岑壑媚。","凭生实内惕，即事多冥契。","息阴眷枌槚，搴芳怀芝桂。","海岳期屡迁，石林路深閟。","经营乖道要，迫窄馀物累。","稽首调御尊，尚饮无生惠。"]},{"t":"赠别叶审言","f":"五言古诗","c":["昔人称好士，乃有黄金台。","黄金亦何物，顾用骄贤材。","叶生被短褐，志力何雄哉。","北走叫阊阖，红云指崔嵬。","终焉无苟售，自保同婴孩。","车服非吾荣，黄金直浮埃。","十年今何官，茅屋歌苍苔。","岂无琅玕树，凤飞故低佪。","一朝脱身去，欻观云路开。","叶君善自爱，往矣无嫌猜。","迷邦古所诮，岂弟贵不回。","愿言吐奇胸，落落排风雷。","尚念穷贱者，衡门守蒿莱。"]},{"t":"晋卞将军墓","f":"五言古诗","c":["江左失其御，强臣布中区。","欢娱一以乖，狂猘无趑趄。","黄屋播草野，彤庭交剑殳。","事枢始谁秉？","捧首如奔狐。","伟此百世士，死与二子俱。","孤衷耿未沫，足以孚豚鱼。","义旗果东指，白日开天衢。","孰最拨乱功，之人或其徒。","伊昔大雅废，清言鄙文儒。","禾黍已横委，衣冠尚舒徐。","屹然见砥柱，独障狂澜趋。","大节固如此，捐生乃其馀。","青简焕遗烈，苍榛閟幽墟。","日夕悲吹多，天高年运徂。","世方用骫骳，犹将愧玄虚。","江涛渺在望，雪涕空涟如。"]},{"t":"赠俞观光","f":"七言古诗","c":["寒窗读书吻正悲，坐闻剥啄走启扉。","冲风踏冻至者谁，俞子访我由剡溪。","相逢把臂话移时，妇人惊笑群儿痴。","俗物病我不可医，眼明求此珊瑚枝。","朝来赠我《天马》诗，忽然掉头去莫羁。","鼻头气息干虹霓，讵能折腰向小儿。","文章技痒聊娱嬉，策勋圣处今毋迟。","繄我爱子莫助之，临岐踯躅徒嗟咨。"]},{"t":"五月廿日","f":"五言律诗","c":["不拟芙蓉佩，终焉挂寂寥。","百年多事始，千里一身遥。","巢燕惊华屋，鞲鹰望碧霄。","苍苍丛桂树，愁绝小山招。"]},{"t":"含香道中","f":"五言律诗","c":["残日亭犹远，轻风帽易斜。","稻畦低没鹤，草径曲行蛇。","经世知无策，谋生会有涯。","殷勤理黄菊，留眼待秋花。"]},{"t":"客夜偶书","f":"七言律诗","c":["历历疏萤度眼明，独支高枕数残更。","薄游已倦新弹铗，旧业犹馀未弃檠。","一雨送晴初月色，百虫专夜故秋声。","情知三十非年少，已觉人间有后生。"]},{"t":"上京道中杂诗十二首 其二 刘蕡祠堂","f":"五言古诗","c":["刘君古遗直，祠堂在丘园。","嗟此豪杰窟，文雄歘孤骞。","平生二三策，匪徼明主恩。","琐琐谈得失，无乃市井言。","凭高一长望，若厌车马喧。","微风过疏雨，青山满前轩。","阴晴倏异态，浮云实无根。","悠悠千载心，去去勿复论。"]},{"t":"上京道中杂诗十二首 其四 榆林","f":"五言古诗","c":["崇崇道旁土，云是古长城。","却寻长城窟，饮马水不腥。","斯人亦何幸，生时属休明。","向来边陲地，今见风尘清。","禾黍被行路，牛羊散郊坰。","儒臣忝载笔，帝力猗难名。"]},{"t":"上京道中杂诗十二首 其八 龙门","f":"五言古诗","c":["竦身望龙门，缓辔行兀兀。","溪回愁屡渡，雨横惊暴溢。","两崖俨相向，百水怒争出。","人言马上郎，快意每多失。","自非渥洼种，不得矜捷疾。","飘飘虮虱臣，凛凛鼋鼍窟。","皇灵重覆冒，利涉用终吉。","回睨向所经，千嶂隐朝日。","青林外盘纡，黄流中荡潏。","后来渠未央，君子宜战栗。"]},{"t":"上京道中杂诗十二首 其十一 李陵台","f":"五言古诗","c":["日暮官道边，土室容小憩。","汉将安在哉？","荒台犹髣髴。","低徊为之久，怀古增歔欷。","长风吹旷野，飞雨千里至。","萧条苍山根，草木馀爽气。","常怜司马公，予夺多深意。","奏对实至情，论录存大义。","史臣司述作，遗则敢失坠！"]},{"t":"题马虚中画","f":"五言绝句","c":["人在白云处，舟在清溪曲。","不闻欸乃声，但见山水绿。"]},{"t":"杂诗五首 其一","f":"五言律诗","c":["日月东西行，群动亦不息。","寄身万物中，宁独谢兹役。","所以鲁中叟，遑遑走南北。","圣哲谅已然，旅人能久宅。"]},{"t":"杂诗五首 其二","f":"五言律诗","c":["晨起步南园，旭日朗以清。","葵花众草中，晔晔敷丹荣。","流光非汝私，独尔心自倾。","览物有深怀，伫立方含情。"]},{"t":"杂诗五首 其三","f":"五言律诗","c":["璞玉与宝剑，沦落初未偶。","君看被湔祓，各在千年后。","将身比金石，谁当独长久。","悠悠百代下，相知复何有。"]},{"t":"杂诗五首 其四","f":"五言律诗","c":["孤云澹无心，出山偶为雨。","长风忽吹散，渺渺归无处。","唯馀向来山，突兀青如故。","慷哉鲁仲连，功成身已去。"]},{"t":"杂诗五首 其五","f":"五言律诗","c":["春风著万物，欣欣皆自私。","可怜儿女花，荣悴更相持。","独有涧底松，偃蹇如不知。","何疑杨执戟，草玄鬓若丝。"]},{"t":"人事如草木","f":"五言古诗","c":["人事如草木，一气荣悴之。","外物何预人，而寘喜与悲。","堂堂异姓王，昔者跨下儿。","穷通本邂逅，达者固不疑。","阮生亦隘人，恸哭真奚为。"]},{"t":"煌煌明月珠","f":"五言律诗","c":["煌煌明月珠，未害居浊水。","君看黄河黄，岂解污清济。","我方遗吾形，宠辱齐一指。","悬知破琴戴，未若掺挝祢。"]},{"t":"微云翳白日","f":"五言古诗","c":["微云翳白日，群动何喧喧。","呜呼麒麟儿，化为猴与猿。","登高望四荒，但见黄河奔。","谁哉溯其流，与我归昆崙。","萎蕤青桂花，霜霰日已繁。","岂不有桃李，对之有忘言。"]},{"t":"古意","f":"五言古诗","c":["荆人初得玉，跅足辞岩阿。","持献万乘君，君门正嵯峨。","谁其尸国工，谬以石见诃。","迷邦诚不忍，欺君反同科。","臣口不自明，臣心终靡它。","抱璞重再拜，呼天泪滂沱。","泪尽血可续，玉在良已多。","是事古则然，呜呼今奈何。"]},{"t":"连雨杂书五首 其一","f":"五言律诗","c":["萧萧十日雨，出门竟何之。","不愁道路难，所惧沾我衣。","悠悠看屋梁，作计诚已非。","有酒不解饮，且遂哦吾诗。"]},{"t":"连雨杂书五首 其二","f":"五言律诗","c":["昔慕栗里翁，颇复志耕耘。","偶入翰墨场，把笔学为文。","偃蹇独何成，喧啾浪云云。","念彼荷蓑子，穷年愧其勤。"]},{"t":"连雨杂书五首 其三","f":"五言律诗","c":["虚堂坐无言，缱绻悲宿昔。","常时眼中人，已如不相识。","剥啄者谁子，令我喜折屐。","忽去已莫追，一笑岸玄帻。"]},{"t":"连雨杂书五首 其四","f":"五言律诗","c":["我思仇山人，山川莽回互。","十书九不到，木叶岁频暮。","颇闻近移居，并失梦中路。","得无挈妻儿，倒载入山去。"]},{"t":"连雨杂书五首 其五","f":"五言律诗","c":["今日曷不乐，孤倡无与酬。","兀坐把书卷，展玩不自休。","借问谁所为，其人已千秋。","山雨政可听，拨书置床头。"]},{"t":"夜兴三首 其二","f":"五言古诗","c":["寒星挂疏林，夜色翳馀暝。","鸡声驱行客，出门路方永。","亦有山中人，熟睡初未醒。","而我立于独，婆娑玩光景。","一笑天宇青，此意君自领。"]},{"t":"夜兴三首 其三","f":"五言古诗","c":["举头见残月，叶脱知深秋。","今我曷不乐，岁月如惊鸥。","常怜古志士，辛苦歌饭牛。","空山夜曼曼，政合秉烛游。","临风振吾衣，萧瑟不得留。","小立殊复佳，涧水鸣幽幽。"]},{"t":"述怀","f":"五言古诗","c":["端居有多感，求志无馀营。","夙违金门路，缅爱丹丘名。","谬忝君子顾，捧已厕群英。","卑栖念远引，窘步迷先征。","俛默敦宿尚，低徊阻平生。","伏枕倦中夜，揽衣寄遐情。","上天廓澄穆，列宿扬光晶。","俯视林木改，仰悲鸿雁鸣。","跂子秉微素，十年守柴荆。","希世乖近务，慕隐馀衷诚。","愿言良时晚，庶保幽人贞。"]},{"t":"寄方子践子发","f":"五言古诗","c":["穷居怅无遂，徂岁聿载阴。","飞翘陨芳华，候虫厉哀音。","急飔扇丛薄，泫露栖乔林。","抚景慨往古，端操思继今。","折兰间幽佩，解缨濯清浔。","石林窅葱茜，佳柏郁萧森。","遗世岂予敢，匡时非我任。","览已谢高轨，即事念所钦。","缠绵阻道里，缅邈眺冈岑。","委怀伫芳讯，贻好在规箴。"]},{"t":"寄俞子易","f":"五言古诗","c":["閒居寡欢豫，枉驾忻周旋。","清言迈修夜，朱火销馀烟。","嘉会良不易，郁抱罄所宣。","揆余徇微业，春冬屡徂迁。","著徽怍往哲，驰芳谢时贤。","眷兹企三益，挥袂增慨然。","杪秋凄且厉，郊圻旷阡眠。","振飙卷飞藿，积雾迷遐川。","契阔岁复流，瞻望情所牵。","存期尚勿夺，辅仁庶不愆。","紫芝无新曲，白驹有遗篇。","矢心遂招要，赠言比芳荃。"]},{"t":"东园晚归","f":"五言古诗","c":["淟涊婴近务，超遥爱佳辰。","兴言望东菑，良苗蔼津津。","鄙人昧时趋，旷途夙所遵。","幸远簪组累，稍欣田圃邻。","兀兀登故畦，悠悠睇城闉。","理秽出新竹，撼枯落荆薪。","夕日逗远川，馀晖散衣巾。","亹亹观物变，依依念农人。","渠渠长者言，恻恻非贱贫。"]},{"t":"送朱仲山之京","f":"五言古诗","c":["麒麟出渥洼，意欲周八极。","刍豆岂不多，未便甘伏枥。","念君抱耿耿，坐视暄凉易。","忽辞白发亲，去作青云客。","应恐邓仲华，笑尔长寂寂。","鄙人属有念，未办经世策。","青灯雨如线，穷巷方偪仄。","县知掺斧斤，不必睨樗栎。","往哉布汝怀，庶用副前席。","勿云万户侯，自可谈笑觅。","百年滔滔内，岐路足南北。","出处会有为，聚散奚暇惜。","歌我辛苦词，送子远行役。","峥嵘壮士志，惨淡游子色。","那无平生期，慎尔保金石。","莫将贾生泪，先为离别滴。"]},{"t":"舟中偶书","f":"五言律诗","c":["我舟合江浒，水清石额额。","念此殊可嬉，如何有行役。","沙头白发翁，扪虱了晨夕。","茅茨八九椽，终岁阅过客。"]},{"t":"休日集于城南","f":"五言古诗","c":["投耒从远游，牵世乖明略。","岂不有简书，未能置丘壑。","崇冈近盘互，春物纷照灼。","休沐集诸彦，迂趾惠前诺。","稍空林中尊，复咏霞上作。","迢迢历墟垄，靡靡瞰城郭。","修阳荫晴渚，野樱散朱萼。","抚时悼推斥，毕景顾栖托。","损益向子明，才能贾生薄。","眷言观岁寒，无将愧场藿。"]},{"t":"制司马公祠堂","f":"五言古诗","c":["朔风破沧溟，白浪无馀地。","可怜甘棠树，乃尔能蔽芾。","借问谁所遗，马公古能吏。","当年印累累，庶务剧于猬。","藏龟不待灼，骋骏无留辔。","偪仄兵马区，蔼然承平意。","晏安亦聊尔，国步方不易。","至尊久尝胆，壮士频裂眦。","煌煌青冥钺，可同牛刀试。","呜呼豪俊人，竟偃风云志。","致身岂云卑，生世已其季。","安知颍川守，遂非庙堂器。","严祠闭寂寥，古木合苍翠。","平生瓣香祝，毋乃儿女事。","如何百载下，能堕看碑泪。","永惟茂陵翁，苦心抱天艺。","力耘宜有收，黾勉观来裔。","渠渠桑梓恭，喋喋市井议。","庶哉瞻前修，树德毋自畏。"]},{"t":"送人赴卢阳学官","f":"五言古诗","c":["播非人所居，潭阳实其邻。","荒淫杂巫鬼，哀怨馀骚臣。","念予有行役，水陆弥数旬。","乃知皋比座，伫承文翰宾。","遐徼指天末，男邦控城闉。","俎豆当在列，冠裳定来臻。","足明理化盛，演溢周穷垠。","广陌望八荒，出车日辚辚。","蛮荆孰无适，忠信惟书绅。","简书有程期，取别无逡巡。","扬镳触炎热，振铎惊远人。","沅水春荡潏，楚峰莫嶙峋。","行行慎其度，离别何苦辛。"]},{"t":"晓望","f":"五言律诗","c":["城头鸦鸣曙，起坐理冠帻。","开窗写遥望，烟雾竟川泽。","喧喧市声动，漠漠井气白。","如何山中人，岁莫尘埃客。"]},{"t":"发金陵留别一二同志","f":"五言古诗","c":["盛名不易居，直道我所遵。","虽枉嘉遁志，未渝白圭言。","罢钓出沧海，迥帆溯江濆。","城闉远灭没，风水屡崩奔。","萧条故交地，怆悢游子魂。","始雷茂阳泽，孤生限穷鳞。","沈翔自殊势，衰荣实同根。","战胜物可遗，目击道已存。","乘桴讵无取，绝弦难具论。","寄言同心子，毋徒念加餐。"]},{"t":"龙湾夜泊","f":"五言律诗","c":["乘潮出远浦，日莫北风平。","高亭不可望，遥遥笳鼓声。","月明寒雁下，江空夕烟生。","非关川途念，沈忧坐自盈。"]},{"t":"宿云黄山作","f":"五言古诗","c":["束发弄文史，挂席去瀛壖。","邂逅乖良会，摈落迨兹年。","息景念生理，洗心宾象筵。","恭惟上皇代，异人秘灵诠。","宗师既逾海，兹山亦栖贤。","金棺灭双树，宝箧缄红莲。","仰窥摄诱功，信知愿力坚。","内愧实菲薄，冥通未精专。","褰裳碧峰雨，焚香石林烟。","綵翠何纷糺，苔涧窅洄沿。","寻幽匪外适，栖真冀重宣。","二边离有无，五浊空腥膻。","岂伊俄顷用，庶谢平生缘。"]},{"t":"逸山过姚紫英别业","f":"五言古诗","c":["逸山诚复佳，逸人不可逢。","何言一笑顷，得此苍髯翁。","今晨过其庐，碧苔灭行踪。","坐我松竹间，野蔌罗甘丰。","初无惊世谈，颇多旷士风。","念昔去岩壑，辍耕白云中。","白云故无恙，我乃羞樊笼。","祗应山林癖，未易药石攻。","高期出邂逅，意气将无同。","十年旧泉石，忽忽蟠吾胸。","起视白日低，归禽乱西东。","拔地森四壁，搀天唯一峰。","复闻麻谷幽，近与金盖通。","山态方屡改，泉源殊未穷。","湫然一区内，嗟我何憧憧。"]},{"t":"次韵答蒋明府先生","f":"五言古诗","c":["文章不经济，耽书或成淫。","偶从长者游，稍窥古人心。","不琢岂非玉，无弦孰为琴。","岁宴灯火微，江阔鱼龙深。","愿言报嘉贶，安得双南金。"]},{"t":"和方韶父先生以满城风雨近重阳为韵七首 其一","f":"五言绝句","c":["掩书坐中宵，阶空叶落满。","不见书中人，苍灯梦秋馆。"]},{"t":"和方韶父先生以满城风雨近重阳为韵七首 其二","f":"五言绝句","c":["岂不有膏沐，所慕非倾城。","翠袖日以薄，勖哉岁寒情。"]},{"t":"和方韶父先生以满城风雨近重阳为韵七首 其三","f":"五言绝句","c":["栖迟怜系瓜，梦寐追飞蓬。","去去羊荆州，吴帆渺霜风。"]},{"t":"和方韶父先生以满城风雨近重阳为韵七首 其四","f":"五言绝句","c":["当年白衣人，赖以慰风雨。","不饮政复佳，有酒无用湑。"]},{"t":"和方韶父先生以满城风雨近重阳为韵七首 其五","f":"五言绝句","c":["江瑶配荔枝，胜处终不近。","好丑且勿争，天道有定分。"]},{"t":"和方韶父先生以满城风雨近重阳为韵七首 其六","f":"五言绝句","c":["聋丞遂已矣，目断山千重。","烟霞故无志，胜会何由逢。"]},{"t":"和方韶父先生以满城风雨近重阳为韵七首 其七","f":"五言绝句","c":["寒华衰复荣，东篱几残阳。","蟠桃亦何好，千年期一尝。"]},{"t":"金华北山纪游八首 其一 灵源","f":"五言古诗","c":["偶为山中游，远过云关宿。","苍灯闪初夜，雨气蒸深屋。","时闻清梵音，窈眇松林曲。"]},{"t":"金华北山纪游八首 其二 草堂","f":"五言古诗","c":["迢迢上方界，水木翳清景。","山深不可留，日暮衣裳冷。","凄其怀昔游，百岁嗟俄顷。"]},{"t":"金华北山纪游八首 其三 三洞","f":"五言古诗","c":["仙山高不极，万古积苍翠。","清兴薄暮移，遗迹洞天秘。","岩阿春寂寥，群仙勿予迟。"]},{"t":"金华北山纪游八首 其四 鹿田","f":"五言古诗","c":["披榛度空荒，突兀崖寺古。","幽花杂红白，老屋亚云雨。","前瞻石径微，咫尺不得取。"]},{"t":"金华北山纪游八首 其五 宝峰","f":"五言古诗","c":["下山复上山，蹑屩行沮洳。","宿云冒长岭，旭日映高树。","山僧亦何为，独向城闉去。"]},{"t":"金华北山纪游八首 其六 潜岳","f":"五言古诗","c":["潘公古达人，陈迹閟丘壑。","草生春昼长，鸟啼岩花落。","神交千载上，未敢付冥漠。"]},{"t":"金华北山纪游八首 其七 山桥","f":"五言古诗","c":["行行指木末，路逐飞云上。","时登巨石憩，共听春泉响。","寻源竟莫穷，即事成幽赏。"]},{"t":"金华北山纪游八首 其八 宝石","f":"五言古诗","c":["暮投招提境，明发首归路。","举头望山椒，遥认经行处。","重重岩壑间，苍然正烟雾。"]},{"t":"中秋会宿浦阳江上分韵得仰字","f":"五言古诗","c":["尝窥仙华录，胜践心所仰。","蹉跎二十秋，故尔劳梦想。","名谈出邂逅，高槩馀佛彷。","节至月仍圆，别来山似长。","百年空中絮，此会知难两。","欲去吾未能，不饮君宜强。","露蔓多夕滋，风竹留晚响。","岐路方悠悠，云何税尘鞅。"]},{"t":"龙山九日","f":"五言古诗","c":["鬓色沧海澨，弥年窘将迎。","属兹九日至，缅爱龙山名。","欣然得胜践，况乃群彦并。","碧萝引幽策，凉泉度飞觥。","志适形可忘，神舒体逾轻。","鄙劣竟何取，腼颜结华缨。","登高谢能赋，徇禄惭归耕。","幸此农事休，万宝咸告成。","庶竭一饷乐，持用夸升平。","月出众山静，天空夕云惊。","先民贵无荒，简书今有程。","怅焉难久留，振袂松风生。"]},{"t":"雍熙僧舍偶书","f":"五言律诗","c":["幽窗悄无寐，落叶不可数。","风惊叶间露，中宵听成雨。","起视天正碧，万里若垂宇。","兹予亦何为，兀兀守环堵。"]},{"t":"送杨学正还馀姚","f":"五言古诗","c":["舜江吾旧游，风物殊不恶。","江水天际来，宛宛带郊郭。","云帆渺沙溆，翠幛森楼阁。","别离不可念，此日忽已昨。","想见春水生，烟柳仍濯濯。","君胡久去此，三径独盘礴。","空斋耿灯火，月冷潮声落。","近闻故人书，远致江上作。","白驹幸无遐，淮阳讵云薄。","招要忻良会，绿酒春可酌。","采芹有遗篇，风雩多新乐。","因君讯同志，何用慰离索。"]},{"t":"奉府帖赐高年帛晚宿孝义山中赋","f":"五言古诗","c":["捧檄去州邑，承筐布明恩。","讵敢期税驾，惟知惧乘轩。","时春雨新已，嘉木阴正繁。","农人有耕作，羽虫亦飞翻。","感彼物情适，念此王事敦。","悠悠迫长路，靡靡穷郊原。","庶与遗老逢，幸聆长者言。","持以荐芹曝，无惭贲丘园。","低徊白日晚，寂寞苍山根。","吾行匪游衍，此怀谁与论。"]},{"t":"送祝蕃远北上","f":"五言古诗","c":["春风吹九衢，卑卑桃李门。","明堂待松柏，未失山林尊。","相逢今岁寒，是事无深论。","念子抱远志，此道夙所敦。","刊条落其叶，将使见本根。","痛恨日月微，毅然辟浮云。","奈何夸毗子，聚讼生纷纭。","瀛洲富才彦，冠盖如云屯。","去去当遇合，美价倾玙璠。","惟须用卿法，力行尊所闻。","丈夫必有事，寤主在一言。","上以禆圣学，下以安元元。","我如鹤俛啄，岂复思乘轩。","子如抟风鹏，本是天池鲲。","栖栖文学掾，平世何足云。","勖哉保令德，契阔期无谖。"]},{"t":"游宝陀寺","f":"五言古诗","c":["十年望沧海，临流不能度。","苍茫岁华晚，邂逅舟楫具。","拂衣乘天风，挂席随烟雾。","且从蛟门发，暝投翁洲住。","前瞻积水深，岛屿青无数。","梅岑特孤绝，遥见日出处。","寄身人境外，矫首禅关路。","粲粲金砂石，离离白花树。","高期惬幽抱，历览增遐慕。","俯伏苔磴间，庶与真灵遇。","二边非可取，三观何时悟。","㗳然坐忘言，目送寒潮去。"]},{"t":"雪窦纪游八首 其一","f":"五言古诗","c":["移舟泊泉口，我行已信宿。","天寒洲渚生，峰回川途曲。","烟霞兰若高，别墅在林麓。"]},{"t":"雪窦纪游八首 其二","f":"五言古诗","c":["揽衣待明发，石路何幽阻。","日出不见人，林深但多虎。","乳峰稍已近，恐惧那复数。"]},{"t":"雪窦纪游八首 其五","f":"五言古诗","c":["亭亭妙高台，迥出千峰上。","怪松多十围，巨石非一状。","心赏孰与同，昔贤有馀唱。"]},{"t":"雪窦纪游八首 其六","f":"五言古诗","c":["萧然上方境，人稀知地僻。","中峰路难辨，丹山云仍积。","徒闻古仙人，石上馀足迹。"]},{"t":"送曾止善孔庙司乐","f":"五言古诗","c":["周官重司乐，典教专成均。","如何千载下，实去惟名存。","之子负远志，被褐徂冬春。","低徊不自衒，保此席上珍。","小试特豪末，食禄同庶人。","幸与骏奔齿，位卑号仍尊。","既殊仕伶官，况及游圣门。","金石方在耳，颂声未崩沦。","闻风苟有作，薄俗斯还淳。","嗟予领胄子，四术空遗文。","铿锵尚莫辨，论说将何云。","临分用自愧，赠言聊具陈。"]},{"t":"送郑以道","f":"五言古诗","c":["郑君不羁客，漫仕常优游。","故人满天上，独佐岭南州。","岭南风土异，去天将万里。","驲骑如流星，众手挽不止。","到官定多暇，坐对梅花时。","溪石秀可砚，泚笔成新诗。","诗成付回雁，动是春冬隔。","用儒行召君，努力崇明德。"]},{"t":"送王君冕同年归长安","f":"五言古诗","c":["昔忝膺荐送，被褐趋上京。","蒙恩赐清问，汇进陪时英。","束带仕州县，暂为闾里荣。","蹉跎二十年，来拂旧题名。","升沈久已判，存没复堪惊。","忽逢王明府，话旧欣合并。","萧条逆旅中，书帙乱纵横。","坐阅车马喧，澹焉若无营。","虽怀帝乡乐，不受世网婴。","宠辱端可齐，去就一何轻。","空馀绨袍恋，犹轸故人情。","予方徇微禄，未能返柴荆。","终然无补报，白发日夜生。","如何同游处，饯此千里行。","度关秋风起，落木寒蝉鸣。","相思阻良觌，恻怆何由平。"]},{"t":"题杜左司西岩诗卷后","f":"五言古诗","c":["吾闻古达士，大隐非山林。","如何鹓鹭间，白驹起遐心。","遥遥望故山，紫塞缭以深。","峰峦势交集，积翠千万寻。","园庐在其下，门巷常愔愔。","轩窗带流泉，花木久成阴。","舂秫足新酿，亦有书与琴。","终然恋魏阙，未忍投华簪。","平明奉朝退，粉署郁沈沈。","披襟坐高阁，独对西山岑。","爽气坐可致，尘虑安能侵。","勿云须吾土，始用穷登临。","异方苟同得，视古犹视今。","聊为招隐篇，往和岩中唫。"]},{"t":"题象山环溪图","f":"五言古诗","c":["崇山标地灵，万古聚清淑。","堂堂故相家，高风在乔木。","仙翁上天去，逸响今谁续。","优哉四千石，接轸飞华毂。","夫君冰雪姿，乃尔抱幽独。","翩然来帝旁，霞裾俨初服。","侍祠明廷上，厌直斋庐宿。","眷言怀旧居，结构依山麓。","轩窗对晴岚，林杪出悬瀑。","散为百道泉，喷薄翻珠玉。","馀润之所蒙，粳稻丰比屋。","春事日向深，桃源酒方熟。","往来无俗驾，异书仍可读。","归欤定何时，专此溪一曲。","相逢京洛间，红尘眯人目。","披图觌佳致，山水增新绿。","先贤止息处，杖屦存遗躅。","爱山锡嘉名，惠幸及樵牧。","于于后来者，犹或被膏馥。","安得从君游，青云两黄鹄。"]},{"t":"题赵凉公瑞瓜图","f":"五言古诗","c":["庆门集嘉况，异瑞呈瓜田。","生五而成十，奇偶出自然。","观物可知德，发祥匪由天。","愿言植灵苑，永奉君王前。","合形表同休，雅咏流绵绵。"]},{"t":"岁晏","f":"五言古诗","c":["岁晏木叶落，遥见东城隅。","雉堞郁苕荛，列屋何萧疏。","悠悠西南望，赫赫金张庐。","退朝集冠盖，鸣珂沸通衢。","合遝多俊游，并辔飞华裾。","顾盼有光彩，行者为踟蹰。","俯惭筋力微，无从效驰驱。","日斜坐官舍，还拂案上书。","缅彼川路长，感此年运阻。","迟回不能去，叹息将焉如。"]},{"t":"送陈太祝","f":"五言古诗","c":["夫君青云彦，早通金闺籍。","弁服劳骏奔，执事谨朝夕。","忽乘使者车，意气何辉赫。","将指固有严，为务本非剧。","经营礼文事，讵曰期会迫。","定知多馀暇，时复肆游历。","向来佳丽地，触目成陈迹。","西山独偃蹇，不改太古色。","相逢几遗老，慷慨语畴昔。","芙蓉君子花，足以语使客。","我方守一官，兀坐如龟息。","当归更淹留，临别增感激。","长风吹远尘，浩浩千里白。","欲附南飞鸿，安能生羽翼。"]},{"t":"丙子七月十七日同辉公登紫微岩汪生元明许生存仁来会遂宿鹿田寺明日乃由山桥回至芙蓉峰而别追念数十年间并游之士往者已不可作在者又莫之与同两生顾能不惮其勤相从蹑屩行风雨中诚一时清事也第未知后游为何日同游为何人抚事述情成二十韵邀两生同赋奉呈审言子长","f":"五言古诗","c":["吾年未及谢，倦飞已知还。","乃复婴近务，无由纵清欢。","幸与方外士，相从岩壑间。","小憩遂深入，诘曲披茅菅。","昔人有遗躅，缥缈青云端。","高居匪结构，异状如雕镌。","志怪固无取，怀贤邈难攀。","停策访旧游，欲去仍盘桓。","迅飙发中夜，众木号惊湍。","凉秋变袢暑，山深气先寒。","泉石无改色，四时自推迁。","交朋半新故，念之增慨然。","两生亦可人，环佩来珊珊。","携手恣幽步，流目穷遐观。","时于林缺处，遥见城南山。","行行度危磴，悠悠睇层巅。","凝阴閟朝采，玄泽酾神渊。","嘉穟日已丰，蔼焉满中田。","览物多所欣，赏心殊未阑。","后期孰与同，良会当何年。"]},{"t":"试院诸公西湖同泛分韵得仪字","f":"五言古诗","c":["秋杪景将晏，天高雾仍披。","漾舟西城曲，散策南山陲。","重棘幸已撤，累觞欣共持。","及兹酒不空，未害席共移。","会合非可常，简书各有期。","念之动予怀，勖哉慎其仪。"]},{"t":"题松声楼","f":"五言古诗","c":["长松四檐间，落落无与伍。","天清啸歌发，肯作儿女语。","道人有真听，无迎亦无拒。","尚不知有耳，况觅声处所。","起视南山高，明月在庭户。","应念朝市人，闻鸡走风雨。"]},{"t":"送宁上人归吴中","f":"五言古诗","c":["我如云问鹤，久厌雕笼养。","子如海上鸥，初不婴世网。","胡为逐吾辈，饮啄劳俛仰。","得无坐书痴，遂尔生技痒。","欲于一毫端，而现诸万象。","重云连夏秋，雨点大如掌。","三州成巨浸，百水犹怒长。","仓忙揖我去，风蒲映飞桨。","有形天地问，浮萍依浩荡。","向也本非来，今焉亦非往。","临岐将何赠，诗境方渺莽。","幸子颇聪明，莫作离别想。"]},{"t":"至正丁亥春二月起自休致入直翰林夏四月抵京师六月赴上京述怀五首 其一","f":"五言古诗","c":["夙予抱微尚，漫仕遂浮沈。","决去不复疑，甘以投华簪。","春天动使星，空谷发跫音。","仓忙遣就道，载笔归词林。","弱质幸未朽，茂恩一何深。","义当不俟驾，事乃违初心。","揖与亲友别，长眺故山岑。","临觞不能御，朗咏岩中吟。"]},{"t":"至正丁亥春二月起自休致入直翰林夏四月抵京师六月赴上京述怀五首 其二","f":"五言古诗","c":["扬帆越江淮，河水来活活。","吕梁扼其冲，石芒殊峭拔。","溯河柁忽摧，度洪缆遽绝。","前途总安流，风劲桅复折。","兼旬涉险艰，脱命争毫发。","行行薄畿甸，值此正阳月。","皇舆方北狩，前旌晓已发。","疾驱望清尘，我马不及秣。","出关历峻阪，下视原野阔。","涧溪多萦迥，冈岭互盈缺。","旧游如梦寐，古道无改辙。","经时春草变，久旱夏云热。","远行诚苦辛，傥免蒙霜雪。"]},{"t":"至正丁亥春二月起自休致入直翰林夏四月抵京师六月赴上京述怀五首 其三","f":"五言古诗","c":["信宿憩虚馆，平明玉堂开。","微风散灵雨，阶戺无纤埃。","良会秩初筵，芳醪湛樽罍。","内官出黄封，飞鞚天际来。","承平多故事，鄙劣惭非才。","抃跃向宸廷，庆云郁崔嵬。","乞身惧再渎，恋阙空徘徊。"]},{"t":"至正丁亥春二月起自休致入直翰林夏四月抵京师六月赴上京述怀五首 其四","f":"五言古诗","c":["日出旦气清，斋祓趋行宫。","周阹夹驰道，大帐垂穹窿。","鸣鞘下霄汉，别殿临薰风。","摄衣升玉除，穆穆瞻睟容。","谒拜未及已，回光赫重瞳。","诏使侍经幄，通籍丹禁中。","斯荣非所希，十载庶一逢。","怵惕久复前，旅进陪群公。","愿因奉清燕，忼慷输微忠。","衰迟力不逮，劳心但忡忡。"]},{"t":"至正丁亥春二月起自休致入直翰林夏四月抵京师六月赴上京述怀五首 其五","f":"五言古诗","c":["圆象无停运，日驭转西陆。","原野多归人，翩翩共驰逐。","念昔居閒曹，未老先纳禄。","蒙恩列外监，放浪湖一曲。","薄田皆旧畬，敝庐非新卜。","白首重见招，英游并华毂。","寒松虽复凋，幽兰岂再馥。","宣尼讥患失，伯阳贵止足。","时暮复何言，终期返初服。"]},{"t":"仙华方先生析简斋杏花消息雨声中之句为韵赋山中社雨七章和者四人先生于第四章见及顾未能属和今五十馀年诸老皆已下地先生门人在者惟朱仙仲山年八十矣偶逢春社兴怀存殁追次前韵以抒鄙情 其一","f":"五言律诗","c":["贞居远人寰，屋老四山静。","一翁屹灵光，二季亦秀整。","晓闻枫林鼓，雨过邻墙杏。","翛然发孤咏，语尽意方永。"]},{"t":"仙华方先生析简斋杏花消息雨声中之句为韵赋山中社雨七章和者四人先生于第四章见及顾未能属和今五十馀年诸老皆已下地先生门人在者惟朱仙仲山年八十矣偶逢春社兴怀存殁追次前韵以抒鄙情 其二","f":"五言律诗","c":["昔年恸哭地，古剑生铜花。","凄其怀故交，中情乱如麻。","仝彼盛壮时，缓辔扬轻挝。","吁嗟长星坠，无复出汉巴。"]},{"t":"仙华方先生析简斋杏花消息雨声中之句为韵赋山中社雨七章和者四人先生于第四章见及顾未能属和今五十馀年诸老皆已下地先生门人在者惟朱仙仲山年八十矣偶逢春社兴怀存殁追次前韵以抒鄙情 其三","f":"五言律诗","c":["淮阴权奇士，髀肉老始消。","长眉已雪色，頩颜尚红潮。","朋游三数公，于焉共逍遥。","平生经济策，忘言付诗瓢。"]},{"t":"仙华方先生析简斋杏花消息雨声中之句为韵赋山中社雨七章和者四人先生于第四章见及顾未能属和今五十馀年诸老皆已下地先生门人在者惟朱仙仲山年八十矣偶逢春社兴怀存殁追次前韵以抒鄙情 其四","f":"五言律诗","c":["卓哉全归子，离尘返冥极。","却观人世间，千载犹一息。","赠言在吾耳，风规良可则。","欲叩封禅书，探囊竟无得。"]},{"t":"忆别青岩翁归进江上橹书札未相忘岁月遽如许山长春树深地阔云涛阻诗筒杳不来今雨非旧雨 其一","f":"五言律诗","c":["仙华几千仞，峻绝临紫清。","天坛瑶草合，石穴阴风生。","踆踆杖屦末，眷眷丘壑情。","幸有一夔足，雅歌续遗声。"]},{"t":"忆别青岩翁归进江上橹书札未相忘岁月遽如许山长春树深地阔云涛阻诗筒杳不来今雨非旧雨 其二","f":"五言律诗","c":["前修遂不作，良友孰我同。","兀坐守章句，独学无全功。","徒操五色笔，随人画虚空。","悠悠感存殁，惆怅百年中。"]},{"t":"雪","f":"五言律诗","c":["急雪下不止，朔风终夜鸣。","饥虫应蚤蛰，老雁故南征。","生理真何计，沈吟独此情。","山中岁酒熟，不饮竟须倾。"]},{"t":"送友人","f":"五言律诗","c":["乡路三百里，独归衣正单。","凉风紫洲水，斜月白沙滩。","灯火期方远，关山岁欲阑。","倚门应望汝，莫慢驻征鞍。"]},{"t":"秋怀五首 其二","f":"五言律诗","c":["对酒高天豁，登楼落日曛。","乱蝉悲暮叶，老雁赴长云。","落拓嵇中散，栖迟郑广文。","身名竟如此，碌碌复何云。"]},{"t":"秋怀五首 其四","f":"五言律诗","c":["仰古嗟无及，关情极可哀。","祢生才见忌，贾傅直为灾。","世肯怜樗栎，吾曾悔草莱。","小诗聊戏耳，何乃并生猜。"]},{"t":"秋怀五首 其五","f":"五言律诗","c":["风雨仍摇落，江山且滞留。","懒从生事拙，閒惜壮心休。","弱蔓萦攲石，空槎卧洑流。","兴怀到微物，世故剧悠悠。"]},{"t":"柴荆","f":"五言律诗","c":["赤日薄乌帽，柴荆无定栖。","可能诗似锦，乍取醉如泥。","薄业惭渔艇，深衣逐马蹄。","萧条江海兴，芳草故萋萋。"]},{"t":"山中怀友 其一","f":"五言律诗","c":["大府趋群彦，修才复壮龄。","波澜开白昼，羽翼动青冥。","弱质悲殊调，明时敢独醒。","未妨茅屋底，寂寞抱遗经。"]},{"t":"山中怀友 其二","f":"五言律诗","c":["望远空山里，天寒夕梦孤。","林昏行魍魉，江晚变蘼芜。","风雨怜同病，尘沙感壮图。","向来怀古意，回首未能无。"]},{"t":"山中怀友 其三","f":"五言律诗","c":["疏放谁容我，交游重得君。","论文轻咳唾，问俗到耕耘。","一笑能青眼，相思有白云。","春风动闾巷，还往漫纷纷。"]},{"t":"悼双林栗上人","f":"五言律诗","c":["飞锡遍诸方，栖身复故乡。","年随双树老，人与一琴亡。","暗草迷春塔，凝烟锁夜堂。","潇潇今日雨，谁炷影前香。"]},{"t":"元日即事","f":"五言律诗","c":["回首人频异，兴怀谁与同。","尘埃欺白苧，岁月入青铜。","雨急苍茫外，春生浩荡中。","长怜故园树，一一受东风。"]},{"t":"八咏楼 其二 溪南即事","f":"五言律诗","c":["莽莽长川去，行行薄暮时。","山光连睥睨，寒色入旌旗。","夕鸟归飞急，风帆逆上迟。","世情关物理，俯仰寄长思。"]},{"t":"八咏楼 其五 怀杨仲弘","f":"五言律诗","c":["离别惊如雨，蹉跎愧后尘。","秪今才有数，多尔术能神。","玉唾春风湿，烟霄碧树新。","谬惭推吏事，吾敢望平津。"]},{"t":"八咏楼 八咏楼遇方子践 其六","f":"五言律诗","c":["风雨三年别，登临一笑同。","绿莎垂古井，碧瓦映疏桐。","世故违高枕，吾生剧转蓬。","相逢感畴昔，出处愧匆匆。"]},{"t":"刘声之炉亭夜话","f":"五言律诗","c":["儒冠宁误我，壮志自多违。","昭代尊经术，先生尚布衣。","清言今夕共，大隐昔人稀。","预恐苍山麓，无从候少微。"]},{"t":"雨三首 其一","f":"五言律诗","c":["湖阔云如积，天空雨正豪。","风飙兼昼夜，井邑带波涛。","茅屋垂垂破，渔舟故故高。","何妨张仲蔚，环堵自蓬蒿。"]},{"t":"雨三首 其二","f":"五言律诗","c":["稚子吾怜汝，泥行去不难。","凭阑真自笑，高枕敢求安。","天地三辰远，江湖五月寒。","好将遮日手，却把钓鱼竿。"]},{"t":"雨三首 其三","f":"五言律诗","c":["田父愁何诉，龙公怒未休。","千畦沈翠羽，百水散黄流。","小市犹长闭，孤城并欲浮。","谁誇补天漏，此事恐悠悠。"]},{"t":"吴赞府挽诗三首 其一","f":"五言律诗","c":["鹤去愁沧海，鸿飞困朔风。","冥冥方独往，已已竟长终。","莫挂还乡剑，真随厌世弓。","向来曾恸哭，不是为途穷。"]},{"t":"吴赞府挽诗三首 其二","f":"五言律诗","c":["百代龙川子，风流见外孙。","馀生唯白帽，旧业自青门。","浩荡期千载，苍茫哭九原。","仙华云缥缈，愁绝刻舟痕。"]},{"t":"吴赞府挽诗三首 其三","f":"五言律诗","c":["怀古馀哀思，怜君尚典刑。","清谈无俗子，白发死遗经。","客社荒春汐，乡山陨夜星。","夕阳邻舍笛，悽切可堪听。"]},{"t":"春日郊行杂兴三首 其一","f":"五言律诗","c":["忽忽时频异，垂垂花正繁。","登临聊极目，出处可忘言。","风急江光乱，春浓野色昏。","旧游嗟契阔，览物思空存。"]},{"t":"春日郊行杂兴三首 其二","f":"五言律诗","c":["五亩清江曲，为农计末疏。","那无经世策，宜付绝交书。","野笛吹频歇，渔舟去若虚。","卜居能有待，天地本吾庐。"]},{"t":"春日郊行杂兴三首 其三","f":"五言律诗","c":["高兴真谁共，佳辰秪屡经。","天清风细细，花远树冥冥。","胜事今非昔，狂歌醉欲醒。","终南飞鸟外，一发向来青。"]},{"t":"次韵答友人","f":"五言律诗","c":["十载论交地，才皆第一豪。","江湖嗟契阔，风雨梦萧骚。","趋走知无力，标题敢自高。","期君养翎羽，一击可徒劳。"]},{"t":"寄李生","f":"五言古诗","c":["有美维仙李，孤标见碧梧。","高门留雨露，短褐混泥途。","姿悍宁为小，机深或类愚。","洗心须贝叶，游艺及摴蒱。","政尔难藏颖，幡然独抱竽。","从容观近效，僶俛事群趋。","稍废琴心曲，能操犊背书。","谁将穷罔象，莫使避珊瑚。","它日逢何暮，清谈动至晡。","醉醒劳问我，喜怒得令渠。","契阔江湖迥，漂零岁月徂。","青云悲捷径，白日仰亨衢。","秋社枌榆外，南包橘柚初。","飞腾如借顺，能勿笑蟾蜍。"]},{"t":"次韵答陈君采兼简一二同志六首 其一","f":"五言律诗","c":["忆昔双溪上，相逢暮雨时。","交游倾意气，谈笑挹丰仪。","草草中年别，寥寥大雅诗。","受材知有分，丰啬竟谁司。"]},{"t":"次韵答陈君采兼简一二同志六首 其二","f":"五言律诗","c":["不谓飘零日，求贤网四张。","胡然卑小技，乃尔閟孤芳。","宝唾非无色，江鸿讵有行。","散材何所以，徒愧饰青黄。"]},{"t":"次韵答陈君采兼简一二同志六首 其三","f":"五言律诗","c":["十载西州客，论交著处新。","时时谈述作，一一望光尘。","澹月银河晓，暄风玉树春。","幸令窥髣髴，微薄尚何伸。"]},{"t":"次韵答陈君采兼简一二同志六首 其六","f":"五言律诗","c":["亦有贞居子，难忘太古情。","诗筒来绝响，茗椀出新烹。","磊落单传意，萧条异代名。","无为念离别，惆怅不能平。"]},{"t":"洋山夜发","f":"五言律诗","c":["肃肃洋山暮，仓忙拜水神。","吹嘘端有力，漂泊竟无津。","黑夜鱼龙界，皇天蚁虱臣。","生还如偶遂，敢惮历微辛。"]},{"t":"陆氏水轩分韵得扬字","f":"五言律诗","c":["高会轩楹敞，清秋笑语凉。","行云随度曲，野水映飞觞。","坐挹才华盛，衰惭鬓发苍。","新诗穿窈眇，何力共游扬。"]},{"t":"寄黄伯阳","f":"五言律诗","c":["掺别逢春雨，移舟落夜涛。","忽惊沧海大，转觉碧云高。","杨子多奇字，王祥忝佩刀。","深情空缱绻，短发正刁骚。"]},{"t":"送胡允文绍兴录事","f":"五言律诗","c":["斯文千载后，一发渺存亡。","尚喜衣冠旧，能传翰墨香。","春秋严助对，富贵买臣乡。","莫厌官曹剧，诸生在雁行。"]},{"t":"读陈制干遗事","f":"五言律诗","c":["历历青云上，飞扬彼一时。","深春曲江宴，清夜郾城诗。","老去山河在，仙成日月迟。","空言徒有托，千载欲谁期。"]},{"t":"隆山牟先生挽章","f":"五言古诗","c":["井络收英气，文昌返列星。","能官须伐阅，仍世觌仪刑。","漂转逾三峡，森扶并五丁。","芝兰纷满砌，橘柚歘充庭。","它日看空枥，群公羡发硎。","鼎湖惊扫迹，华表讶摧翎。","风物嗟王粲，心期托管宁。","乘桴良已后，抱瑟匪求听。","此道诚何病，明时忌独醒。","迢迢胆北极，衮衮化南溟。","荐剡多新墨，恩袍祇旧青。","故应毡座冷，不愧草堂灵。","食檗馀深味，县车及暮龄。","一朝伤永诀，千古闷遗经。","谬忝鸿私久，徒增雪涕零。","无辞歌薤露，有恨寄泉扃。"]},{"t":"入京道中寄同里诸友","f":"五言律诗","c":["十年州县底，及此望京华。","客路时时雨，春江岸岸花。","何方堪报国，将老更浮家。","可得同携手，山颠复水涯。"]},{"t":"送句龙提举之云南","f":"五言律诗","c":["独抱文章印，驱车背朔风。","行歌万里别，声教百蛮通。","列郡创残后，诸生色笑中。","谁当偕计吏，封殖待新功。"]},{"t":"题天童叠秀轩","f":"五言律诗","c":["名山标巨刹，楼阁在青冥。","别路通禅窟，当轩列翠屏。","暝禽多雪色，偃树尽龙形。","负土新成塔，非才愧勒铭。"]},{"t":"送简县尹","f":"五言律诗","c":["简氏多兄弟，才名萃一家。","嗟君本朝士，出宰向天涯。","度岭三冬雪，行春一县花。","应怜未归客，鞍马尚风沙。"]},{"t":"送赵仲理御史","f":"五言律诗","c":["籍甚声华旧，频年沐盛恩。","校书天禄阁，执法太微垣。","揽辔炎埃豁，挥毫玉露繁。","庸疏徒自笑，投赠欲何言。"]},{"t":"送马伯忱教授","f":"五言律诗","c":["卓荦青云彦，飞腾及妙年。","书成天禄阁，座有广文毡。","九陌车尘外，千军笔阵前。","白头惭倚席，临别思茫然。"]},{"t":"送王道一郎中","f":"五言律诗","c":["使者下青冥，郎官动列星。","扬旌开瘴疠，持斧用雷霆。","远俗难驯化，儒臣解引经。","无如多诖误，能勿望平亭。"]},{"t":"送宋显夫宪佥分题得邵伯埭","f":"五言律诗","c":["谢公千载后，陈迹在淮壖。","遗爱传终古，嘉名配昔贤。","藕花方烂漫，使节莫留连。","移取甘棠树，分栽郢水边。"]},{"t":"送宋翼卿照磨","f":"五言律诗","c":["莽莽关河路，西征独据鞍。","借材莲幕底，养望柏台端。","指日传温诏，朝天正法冠。","广平心铁石，宁惮朔风寒。"]},{"t":"送潮阳苏县尹","f":"五言律诗","c":["夜水藏蛟鳄，秋天卷瘴云。","田多陶令秫，石有大苏文。","巧宦诚为乐，修才况不群。","尚烦驱笔阵，时复张吾军。"]},{"t":"题道士熊君寿母诗卷","f":"五言律诗","c":["跨鹤出山中，春衣密密缝。","度关占紫气，赐酒拆黄封。","介寿慈颜喜，承家积庆重。","苏耽却来否，石上有仙踪。"]},{"t":"题石门净胜寺","f":"五言律诗","c":["十顷苍陂上，山回地势偏。","屋栖黄面老，碑挂赤乌年。","叶叶风荷颤，层层雪瀑悬。","青灯夜寥阒，独照一僧禅。"]},{"t":"试院同诸公为监试官作","f":"五言古诗","c":["文治回亨运，群言协睿谋。","设科存坠典，传诏及遐陬。","风动黄帘晓，霜飞白简秋。","迂临宣上化，精察副旁求。","怀牒鱼鳞集，摛辞茧纴抽。","按行承奖饬，鼓舞望甄收。","冰鉴垂清照，渊珠免暗投。","充庭先品物，入彀总英游。","奏自兰台上，名依桂籍留。","神仙司下土，桃李在南州。","使节光华盛，公堂礼数优。","无能禆末论，倾咏独绸缪。"]},{"t":"游法华山回宿楼氏书房遥望嵩头陀智者国师道场上清五云龙寿诸山而未及至其处赠同游傅生国章 其一","f":"五言律诗","c":["故庐湖水曲，门对法华山。","百里空荒外，三峰晻霭间。","倦游烦汲引，阔步强跻攀。","老怯高寒境，非缘兴尽还。"]},{"t":"游法华山回宿楼氏书房遥望嵩头陀智者国师道场上清五云龙寿诸山而未及至其处赠同游傅生国章 其二","f":"五言律诗","c":["小憩虚斋夕，何人笑语同。","青云一才子，白发两衰翁。","节物逢春好，名区有路通。","未能穷胜践，健走愧儿童。"]},{"t":"题赵公画兰竹","f":"五言绝句","c":["猗兰幽人操，绿竹君子德。","夭夭彼棘心，胡为久吾侧。"]},{"t":"梓山行赠桑生","f":"七言古诗","c":["昔闻山中采药翁，问姓但指檐前桐。","君家本以桑为氏，胡不种桑翻种梓。","桐君采药不学医，桑君学医兼采诗。","朝来索我歌梓山，使我阁笔频支颐。","问君梓树家何处，青山难寻梦中路。","但见清风两袖宽，诗筒戢戢多于树。","长歌短歌亦奚为，坐看药笼悬蛛丝。","种桑种梓俱有术，也应无术医君痴。"]},{"t":"采芝曲赠永嘉林道士","f":"七言律诗","c":["碧峰矗起三十六，老芝千年琢红玉。","帝遣仙人下采芝，迷花失石憺忘归。","忘归几载无消息，蟠桃积核高数尺。","何日青牛驾尔还，肯念金华牧羊客。"]},{"t":"读清江集","f":"七言古诗","c":["元祐儒臣焕星斗，后有作者非其偶。","二龙三凤何缤纷，况乃渊源鲁中叟。","适从尘编识英爽，想见世泽馀忠厚。","长公平生二三策，大廷披腹惊群后。","风流斑斑仲与季，茅茨采椽绝丹黝。","独追古昔寓阳秋，稍抉疵瑕到琼玖。","却蟠馀力归赋咏，古硬清圆无不有。","爰初人文启河洛，下逮百氏分户牖。","空言可托匪末艺，巨笔待援须好手。","典刑未坠乃至今，吾生已幸何云后。","青灯照夜雨如线，奥论微辞烦击剖。","追慕政复惭捧心，赞美胡能付钳口。","从游起死不敢期，傥挹残膏注空朽。"]},{"t":"甲辰清明日陪诸公入南山拜胡侍郎墓回汎舟湖中作","f":"七言古诗","c":["日终甲子斗直辰，持觞远酹胡侯坟。","两桨趁鸥背城闉，四十有四同州人。","半为吴语如季真，湖穷岸出水陆分。","舍舟登途指嶙峋，少年健走黄犊奔。","或乃喝道惊春云，老翁茧足仍后尘。","解衣径眠草为茵，前趋一里趋庙门。","杖藜不得辞微辛，严祠高居绝四邻。","傍为一邱标石麟，升阶鞠躬羞藻蘋。","拜兴有相祝有文，亦或稽首称诸孙。","归途探幽抉荒榛，下睨尘土多虻蚊。","放舟催发无逡巡，胜赏莫许穷涯垠。","开篷列坐罗膻荤，托名乡饮无主宾。","谁欤解事强讨论，欲以穷达为卑尊。","美人今代王右军，口吐秀句天葩芬。","雁行拱立何纷纷，争言我公诗绝伦。","庞眉被褐两山民，闭目宴坐方申申。","舣舟黑亭鸦噪昏，晴杨吹花洒衣巾。","裁诗纪实聊云云，慎勿浪传来怒嗔。"]},{"t":"送傅主簿","f":"楚辞体","c":["吾闻上古之世比屋皆可封，有材不必登王公。","可怜卫青日尊贵，飞将自老风尘中。","傅公平生经济手，却抱一生今白首。","随人骑马著青衫，爽气如虹射牛斗。","出门大笑望长安，长安万里行路难。","行路难，知柰何。","赠君一杯酒，请公听我歌。","昆崙之山兮高巍巍，黄河之水兮清有时。","洛阳少年休太息，东山谢公来未迟。","燕昭之事不足云，陛下圣德如华勋。","愿公功成名遂身早退，鲁连小儿能笑人。"]},{"t":"由苕溪出大湖抵阳羡十四韵","f":"七言古诗","c":["首阳山人饿至死，陶公乃为饥所驱。","大贤出处自有意，腐鼠何得疑鹓雏。","谁初令我堕世网，久抱磥砢行崎岖。","今晨笑与亲友别，烟波泱漭扁舟孤。","穹天大泽合为一，回睨人境茫如无。","向来蚁聚安足恋，而取窘束同囚拘。","暮投高馆灯闪闪，坐谈姬孔歌黄虞。","是间幸可容一息，孰与臣朔肩侏儒。","汗颜俛首饱腥腐，咄子所乐非我娱。","故人殷勤入我梦，云我作计陋且愚。","此生通塞久自断，岂忧一勺忘江湖。","春风二月花蔽野，珊瑚玉树唯空株。","丈夫儿女各有事，为君起坐生长吁。"]},{"t":"次韵方子践雪中见寄","f":"七言古诗","c":["前年江南雪一尺，腐儒共走誇三白。","宁知有客卧欲僵，冻骨棱层撑铁石。","今年复此雪塞门，江湖无处浮言樽。","野风萧萧日色死，看人射虎苍山根。","牛衣覆寒夜复夜，金石馀音惭慰藉。","平生万卷定安施，一瓻送我当渠借。"]},{"t":"题陵阳牟公紫阳方公诗卷","f":"七言古诗","c":["两翁风流埽地无，文章光燄埋丘墟。","纷纷小儿政疾走，安用佩玉飞长裾。","忆昔登堂三十载，梦想时复瞻眉须。","昆虫闭关水返壑，孰使骊龙道颔珠。","愿言保此勿轻出，幸免儿辈相睢盱。"]},{"t":"题大瀛海道院","f":"七言古诗","c":["丹山之山青崔嵬，隐居旧隐山之隈。","千年土鼎为谁出，深崖古像松声哀。","鸿飞天上爪在雪，过者莫睨君能来。","想当月斧乍挥霍，奔走属役皆仙才。","卷藏瀛海归一粟，顾盼瞬息生风雷。","森然幻有启神界，白日照耀金银台。","昔闻使者兹入海，楼船烟雾何时回。","君其置此勿复念，少须碧水扬黄埃。","九重蠖濩陛下圣，方士未易誇蓬莱。","琳宫贝阙长望幸，天高海阔心悠哉。"]},{"t":"题松溪图","f":"七言律诗","c":["独骑瘦马走赤日，忽对画图双眼明。","想见高人茅屋底，石床卧听松风声。","秋风渐高霜露白，松根茯苓已堪食。","郁纡迟暮祗自怜，卷图还客三叹息。"]},{"t":"题周鍊师云崖图","f":"七言古诗","c":["我本山中牧羊客，偶然失脚红尘陌。","矫首丹崖不可攀，但见层空暮云碧。","楼居仙人元不死，天长地久无消息。","骑麟翳凤者为谁，道上相逢不相识。","披图示我旧游处，流水桃花尚春色。","为言白石久已烂，茯苓无复成琥珀。","忽然长揖不肯住，飘若流星去无迹。","若为握手赋归来，永与人间风雨隔。"]},{"t":"赠熊天瑞先辈","f":"七言古诗","c":["熊君南州山泽臞，敝衣不满六尺躯。","年丁七十气尚粗，拨弃舟楫违江湖。","尘埃掠面冰生须，北走梁宋至皇都。","举头仰瞻天子居，姓名无由达公车。","何王之门无长裾，君惟抱瑟王好竽。","寒风萧萧雪塞庐，退从诸生咏唐虞。","诗成篝灯手自书，字如冻蝇密复疏。","食可无肉出无驴，为我蹝履来于于。","曰予其归无所须，一言用比明月珠。","我方守官橛株拘，嗒然忘言据槁梧。","童子穰穰环座隅，笑我腹笥太空虚。","感君远来增叹吁，爱莫助之将何如。","翰林主人揭大夫，与君少若同队鱼。","岩栖穴处多其徒，君归而求宜有馀。","长歌鼓缶声呜呜，青天自高云自孤。"]},{"t":"送李宪使赴燕南分题得乌飞曲","f":"曲","c":["台中树，枝上乌无数。","当年元只为公来，今日从公却飞去。","赵北际，燕南垂。","道傍绿树多好枝，公之所憩乌所依。","公毋亟行乌勿飞，问公此去何时归。","上林春深树如织，公归但听乌消息。"]},{"t":"赠夏德颂","f":"七言古诗","c":["夏君怀抱何磊落，卜居不肯依城郭。","丙舍新开近墓田，雪柏霜松翳丘壑。","一朝兴来不可遏，万里黄尘走京洛。","叩门遗我尺素书，俪玉骈珠相照灼。","为言家世本臞儒，馀力惟知事耕凿。","穷年甘与鹿豕游，敢希鸿鹄翔寥廓。","秪今远来亦有意，求诗元不求官爵。","华星秋月幸分辉，持向山家慰萧索。","我闻君言重太息，感君望我殊不薄。","清时杂遝富才彦，笞凤鞭鸾趍馆阁。","挥毫成风墨成雨，瑞锦披张分制作。","一言引重力千钧，青云骥尾端堪托。","顾我方为句读师，掇拾残编味糟粕。","坐隅童子日呶呶，平生雅意浑销铄。","奚暇清吟发天巧，剪红刻紫供嘲谑。","君归卉木尚馀春，况值新篁初解箨。","传家有书故可读，有石可眠泉可酌。","大胜山人来索价，低头欲就微官缚。","我虽龌龊坐无毡，有客如此良不恶。","戏拈笔管和灶煤，为君聊赋山中乐。"]},{"t":"风树唫为李生作","f":"曲","c":["返照入深林，牛羊在丘垄。","风吹白杨树，叶叶各自动。","如何当此时，孤子万里归。","有琴未成声，遽欲弦吾诗。","吾懒言诗子姑去。","抱琴听子风中树。"]},{"t":"题钱舜举画","f":"七言律诗","c":["鸟雀鹰鹯皆羽族，强之食乃弱之肉。","两雀亦分弱与强，一遭搏噬一高翔。","画师描貌劳意匠，诗人见画齐惆怅。","人间万事无不然，鸡虫得失安足言。"]},{"t":"题李氏白石山房","f":"七言古诗","c":["名山秀出鄱江曲，上有立石如立玉。","尚书履声忽已远，隐者新居在盘谷。","花开鸟鸣春昼永，白云重重养乔木。","夫君亦复称其家，有书能藏且能读。","露钞雪纂久愈富，何啻邺侯三万轴。","山灵翕霍谨呵护，夜半虹光发深屋。","引泉天井助芳润，大胜吴侬饮山渌。","我欲从之不可到，细字长书俄满幅。","毫分缕析极根柢，大义森然见条目。","鄙人愧莫知所对，叩请安得留更仆。","颇闻石洞閟遗音，龙门馀韵须君续。","临风倾咏寄绸缪，衰朽终期挹膏馥。"]},{"t":"题张清夫心远堂","f":"七言古诗","c":["吾闻古来贤达士，不择山林与朝市。","百年尘瓮两醯鸡，鹏鴳逍遥俱可尔。","夫君平生潇洒意，俯睨轩裳犹敝屣。","翩然一舸鲈鱼乡，归来不待秋风起。","忘言兀兀坐终日，天地古今齐一指。","但见山高湖水深，青螺荡漾银杯里。","柴桑之人去我久，风味何妨略相似。","神交冥寞云海长，目送归鸿眇千里。"]},{"t":"送孙君文判官","f":"七言律诗","c":["笑语匆匆似梦中，衣裳俄复判西风。","残蝉落日那堪别，瘦马长途喜未穷。","岁事已空南亩稼，归期应老故山桐。","兴来尚有平生棹，载酒何时觅钓翁。"]},{"t":"寄陈君采","f":"七言律诗","c":["江淹文采碧云消，潘岳才华玉树彫。","后尔千年开捷钥，森然作者见风标。","琪花夕日辉相并，金匮名山路未遥。","剩欲倾心数还往，高期无使竟萧条。"]},{"t":"次韵答吴正传","f":"七言律诗","c":["诸老彫零半九原，后来英发见苍然。","高标能复居人下，缓步犹须出我前。","天马为谁生月窟，仙禽有日到芝田。","论心待取同倾盖，可使空回雪夜船。"]},{"t":"寄叶审言","f":"七言律诗","c":["千里相思黄叶初，喜传消息慰离居。","姓名漫入山公启，怀袖元无贾谊书。","已分耕芸供赋敛，胡令汲引到樵渔。","临歧踯躅频回首，风雨萧萧雁正疏。"]},{"t":"九日","f":"七言律诗","c":["独立凭高发兴新，霜清露白复佳辰。","绿樽到手不解醉，黄花满头应笑人。","梼边老僧幽期失，岩南诗客新句频。","秋犬此日并回首，鹅雁寄书愁未因。"]},{"t":"次韵山南先生遣兴 其二","f":"七言律诗","c":["蒲团兀坐久忘机，何暇重寻是与非。","老雁长云天渺渺，晚花寒蝶思依依。","起看丹灶春无恙，欲试青鞋雪未晞。","鹏鴳逍遥端可耳，玉堂何必愧柴扉。"]},{"t":"寄仇仁父先生","f":"七言律诗","c":["一官十载尚沉沦，门巷萧萧白屋贫。","自有陶公为社友，从呼杜老作诗人。","儿曹故复轻前辈，俊步谁当出后尘。","招隐诗成无处寄，莫云凝碧坐愁神。"]},{"t":"寄朱十八丈判官","f":"七言律诗","c":["金榜凄凉已十年，风流文采故依然。","香山老去谁同社，栗里归来尚有田。","怀古坐看西日落，得春宁问北枝偏。","清泉白石多深趣，千载心期入近篇。"]},{"t":"寄友人","f":"七言律诗","c":["系舟一别云水乡，暮川葭菼空苍苍。","漳滨卧病它年忆，渭北题诗春日长。","芜菁作花已烂漫，杨柳飞絮苦颠狂。","闻道茯苓已堪斸，迟子青鞋经涧冈。"]},{"t":"送友人之京","f":"七言律诗","c":["偶缘送远接清游，烟雨东城晚树幽。","离别自应多感慨，笑谈未害各风流。","百年芳草频频合，万事孤云故故浮。","大华黄河入回首，春风愁绝李膺舟。"]},{"t":"忆友人","f":"七言律诗","c":["无复高谈慰索居，壮心零落竟何如。","人间漫有金台梦，身后谁传玉枕书。","半亩苍苔埋璧地，一声白雪断弦初。","芙蓉峰下闻吹笛，泪滴春天草木疏。"]},{"t":"哭李无逸","f":"七言律诗","c":["青春未受二毛侵，谈笑俄闻变古今。","千日却醒徒有望，九原莫作遂何心。","平生欠荷刘伶锸，此夜谁弹子敬琴。","水乐亭西烟草碧，旧游回首重沾襟。"]},{"t":"杂兴 其一","f":"七言律诗","c":["昔从六客堂前客，共买何山渡口船。","杉松夹道得古寺，风雨漫山连杜鹃。","忆别老僧如昨日，待分幽事及他年。","春江正绿不能去，胜践萧条秪可怜。"]},{"t":"杂兴 其二","f":"七言律诗","c":["几回拟作送春诗，出户春风去不知。","叶底孤花犹入眼，竹根稚笋欲过眉。","久抛书卷都如梦，閒看香烟偶似痴。","寄语平生张仲蔚，一欢相属竟何期。"]},{"t":"杂兴 其三","f":"七言律诗","c":["刘生去涤相如器，朱子新裁贾谊书。","百代风流今视昔，十年怀抱我怜渠。","故应曾对谈谐乐，也复能容礼法疏。","风雨潇潇守环堵，秪今可望故人车。"]},{"t":"山中夜归","f":"七言律诗","c":["漫山松叶行径迷，独穿荦确幽步迟。","惊风低草山虎过，寒月挂树天星垂。","泉鸣荒冢夜牢落，露洗青林光陆离。","茅檐抱膝者谁子，歌阕饭牛声正悲。"]},{"t":"三月三日西湖舟中","f":"七言律诗","c":["黄尘奔走愧平生，对客犹称旧姓名。","此事正堪三太息，秪今忍负四难并。","放舟乍落空濛境，送酒元无窈窕声。","金谷兰亭嗟已矣，不妨时暂濯吾缨。"]},{"t":"哭陈茂卿","f":"七言律诗","c":["多病文园鬓未霜，可人风味故难忘。","岂期夜壑舟无定，竟使春天草不芳。","卖药几时来海上，遗文须我访襄阳。","谁怜后死仍漂泊，云白山青自故乡。"]},{"t":"宣城客中偶书","f":"七言律诗","c":["眼看春霄拥胜流，漂零回首愧沙鸥。","黄尘乌帽知谁为，白饭青刍复此留。","未必嵇康能作吏，何妨李广不封侯。","敬亭云鸟知无恙，款段惟须逐俊游。"]},{"t":"梳头得白发","f":"七言律诗","c":["偶逐飞云别涧冈，解缨聊尔濯沧浪。","襟怀久已无山水，客鬓谁令有雪霜。","未必丹砂真却老，可堪白首更为郎。","前修未远斯文在，努力无愁歧路长。"]},{"t":"山南先生挽诗","f":"七言律诗","c":["仰惊乔岳失嶙峋，千载风流可复闻。","鼎有丹砂轻县令，囊无薏苡诧将军。","苧袍岁月孤青简，石室文章閟白云。","泪尽侯芭悲独立，短衣高马秪纷纷。"]},{"t":"喜方韶父先生至兼怀山南先生","f":"七言律诗","c":["梦觉秋宵失薜萝，尚烦青简慰蹉跎。","山中旧别期犹在，岁晚相逢感易多。","华表神仙成寂寞，灵光风雨见嵯峨。","百年珍重斯文寄，趼足脩程可柰何。"]},{"t":"韶父先生有诗复次韵以和","f":"七言律诗","c":["两翁故复可怜人，倾盖长安四十春。","华屋山丘如隔日，夜床风雨得弥旬。","书签药裹仍仍在，橘刺藤梢一一新。","漫写馀哀寄冥漠，大荒谁见下麒麟。"]},{"t":"送王傅朋静江教授二首 其一","f":"七言律诗","c":["丞相威名震百蛮，萧条异代得吾贤。","宦游忽过三湘去，家学应令四海传。","北望犬牙连上国，夜占鹑尾直中天。","炎风朔雪皆王土，未觉青春雨露偏。"]},{"t":"送王傅朋静江教授二首 其二","f":"七言律诗","c":["碧莲峰下驻飞骖，风土遥知久自谙。","会有新书禆禹贡，坐闻旧俗化周南。","深篁尽日迷山鬼，毒草无时起瘴岚。","珍重斯文强餐饭，漫誇丹荔与黄柑。"]},{"t":"送扬州傅学正","f":"七言律诗","c":["全淮控制列城遥，尚想青春虎豹骄。","一日江山走珠玉，万家灯火沸笙箫。","喜逢才俊登文署，好颂升平答圣朝。","芍药琼花儿女事，可缘风月逗华镳。"]},{"t":"遣兴","f":"七言律诗","c":["青云如梦慨平生，白发惊春忽数茎。","渐觉交游随日别，强知颜色逐人行。","百年松槚谁能去，五亩烟霞故可耕。","妄念扫除浑欲尽，少游何得尚相轻。"]},{"t":"次韵子践秋社归岩南","f":"七言律诗","c":["久悟清都是梦中，未嫌短褐任飞蓬。","时情冉冉心如醉，世议纷纷耳欲聋。","会种枌榆依汉社，共谈禾稼续豳风。","蹉跎偶负平生约，已复人间岁一终。"]},{"t":"杭州寄里中一二同志","f":"七言律诗","c":["故山有路去无从，灯火关心梦不通。","浪走红尘真自笑，旧游白社竟谁同。","胸中好贮千岩秀，眼底徐观万马空。","风雨未休鸿雁断，此怀渺渺故难穷。"]},{"t":"客楼雨中","f":"七言律诗","c":["江城飘泊动经年，尽日高楼阅过船。","睡起小窗初听雨，岸旁垂柳已生烟。","坐抛岁月今如此，每望云山欲泫然。","尚喜游从得诸彦，时将乐事寄新篇。"]},{"t":"送杨山长归钱塘","f":"七言律诗","c":["百里乡心海雁飞，三年官况野鸥知。","儿童早已占归信，弟子应能颂去思。","茅屋荒田春草草，杏花深巷雨丝丝。","人生适意须行乐，驷马高车恐未迟。"]},{"t":"章德懋同登车盖山","f":"曲","c":["城南日日望苏湾，碧树童童盖一山。","何意兹辰成邂逅，与君携手共跻攀。","钩衣乱石通高步，着面和风启醉颜。","尚爱铭碑多楷则，俗书且勿斗妖?。"]},{"t":"湖州遇叶士心因寄郭祥卿架阁","f":"七言律诗","c":["谢公城下蹋春晖，最忆东园夜不归。","落月清樽波潋潋，高花银烛雾霏霏。","未愁强醉罗衣湿，政恐重来燕麦稀。","大地风涛竟如料，九霄一鹄看横飞。"]},{"t":"大卿牟公挽诗 其一","f":"七言律诗","c":["云光一夕失崔嵬，多上相逢泪雨推。","夹道共看丹旐去，遗民犹忆绣衣来。","萧萧悲吹蘋花冷，渺渺乡山杜宇哀。","哭尽贞元旧朝士，临歧无语重徘徊。"]},{"t":"大卿牟公挽诗 其二","f":"七言律诗","c":["后生无复望仪刑，青史徒烦列姓名。","穷有遗文成钜冢，死无新爵上铭旌。","瓜田方任蓬蒿没，玉树偏依雨露生。","旧笏满床知未坠，翰林风月向来清。"]},{"t":"次韵牟主簿南湖客中","f":"七言律诗","c":["遥望仙桡度碧湖，翩然高兴不枝梧。","也知白发行相待，无奈青山不受呼。","过眼光风殊猎猎，沾衣多露已涂涂。","相逢幸及南枝好，一笑聊须引百壶。"]},{"t":"次韵姚子敬教授筠庵别业","f":"七言律诗","c":["故园烟树渺江关，长愧求閒未得閒。","客路独愁黄叶下，高人正在白云间。","卜邻傥遂容依止，载酒终期共往还。","未害看山仍拄笏，一竿付我钓沧湾。"]},{"t":"次韵别程晋辅教授","f":"七言律诗","c":["落拓江湖久不归，相逢还及试春衣。","忽闻烟际兰桡动，谁共花前玉斝飞。","青眼故多知己在，黑头未觉壮心违。","赤霄孔翠吾何望，喔喔邻鸡尔自肥。"]},{"t":"草意","f":"七言律诗","c":["澹烟斜照旧离离，吐漫芳心欲向谁。","可是忘忧能自得，若教指佞定无私。","东风江上何人识，南国春来有梦知。","留取青青承雨露，术应红紫浪相疑。"]},{"t":"阙下口号","f":"七言律诗","c":["遹骏先猷在作人，忝陪多士奉明纶。","端闱乍启清光近，胪句高传茂典新。","奎壁照临回景运，风雷鼓舞契昌辰。","不才何以酬天造，徒咏菁莪乐至仁。"]},{"t":"赐第后归谒郡府承为置宴口号","f":"七言律诗","c":["拜赐才沾雨露香，又惊盛典出黄堂。","鸣驺合遝迂千骑，坐席雍容累百觞。","他日同乡修故事，不才终古被馀光。","承宣得意逢明牧，诸彦能无共激扬。"]},{"t":"郡厅宴集之明日乡先生复为置酒重述口号","f":"七言律诗","c":["去年此日宴琼林，雨露光华映古今。","称庆谬承宾礼重，徼荣弥觉主恩深。","少须天诏从容至，坐看宫花取次簪。","千载斯文寄来哲，可应外物累初心。"]},{"t":"喜赵继道至有怀陈君采","f":"七言律诗","c":["匆匆聚散定何常，耿耿心期故未忘。","草木关情人事异，云霄回首路岐长。","交游历落银河隔，制作纷纶瑞锦张。","为语何时共倾倒，秋床风露已生凉。"]},{"t":"寄曹子讷于寿道二同年","f":"七言律诗","c":["忆同鹄立簉天关，清漏无声虎豹闲。","黄榜未开齐望拜，紫衣高唱遽分班。","已惊恩出寻常表，更羡身居季孟间。","海国邻疆幸无远，可容接武向蓬山。"]},{"t":"寄别宋推官","f":"七言律诗","c":["目断仙帆去莫从，翩然心逐北飞鸿。","未忘绿幕追游盛，况忝黄堂礼数崇。","南国几人歌召伯，汉廷有日相于公。","悠悠聚散何堪计，趋走终期出下风。"]},{"t":"送姜学录","f":"七言律诗","c":["短褐萧条两鬓苍，逢人犹解说春坊。","云霄有路新推毂，风月传家旧佩囊。","此去官曹虽冷落，不妨门户暂辉光。","况闻寮友多华胄，休暇过从乐未央。"]},{"t":"送盐官傅都目","f":"七言律诗","c":["春风匹马去翩翩，老佐名州鬓未班。","遥数驿程知到日，坐令官府静如山。","河塘灯火机声里，墟落盐烟海气间。","历历旧游如梦寐，可容乘兴一追攀。"]},{"t":"送贡教授致仕归里","f":"七言律诗","c":["宦情乡思两依依，独裹寒毡去若飞。","岁晏忍为千里别，林间惊见一人归。","官河远树迎仙棹，夕日暄风飏綵衣。","漫使临歧生怅望，可容泉石借馀辉。"]},{"t":"送三高祠陆主奉","f":"七言律诗","c":["垂虹古祠烟树新，昔贤高致久无闻。","画图想像空陈迹，谱谍流传喜到君。","春水白鸥分座席，寒泉秋菊荐炉熏。","临歧何限沧洲意，目断风帆天际云。"]},{"t":"送陈推官之信州","f":"七言律诗","c":["三朝两世掌丝纶，异代仍瞻玉树新。","尚喜传家馀宦谱，又闻议狱用儒臣。","中年离别情何限，南渡风流迹未陈。","遥想郡斋多暇日，肯怜州县正劳人。"]},{"t":"送胡古愚兼简道传博士","f":"七言律诗","c":["坐拥皋比十载馀，忽闻飞鹗上公车。","此行未可轻投笔，随处犹须小曳裾。","灯火尚惭馀事在，云霄转觉故人疏。","为言留滞今头白，无用诸公荐子虚。"]},{"t":"送淮海书院丘山长","f":"七言律诗","c":["遥望官河驻綵桡，春深绛帐不萧条。","已惊雨露恩光厚，还喜山川物色饶。","尽日楼台人载酒，隔江灯火夜吹箫。","定知馆下多才彦，政乐风雩对一瓢。"]},{"t":"留别钱翼之","f":"七言律诗","c":["矫首清标二十霜，白头倾盖郑公乡。","忘形肯厌追游数，借润频飞翰墨香。","世态浮云看不定，别情流水去方长。","杏花时节霏霏雨，谁共春风举一觞。"]},{"t":"诸暨休日偶书","f":"七言律诗","c":["一室萧然似冷官，更无车马驻江干。","天清不断丝丝雨，春浅犹生阵阵寒。","公事痴儿何日了，云山图画要人看。","轻风正满微黄柳，谁与相从试凭栏。"]},{"t":"次韵答徐文蔚","f":"七言律诗","c":["一别溪头十五春，归来乌帽尚黄尘。","故应用意崎岖外，未忍忘情寂寞滨。","图画云台非我事，挂冠神武独何人。","也知州县徒劳耳，相见空惭白发新。"]},{"t":"送顾仁甫上计京师","f":"七言律诗","c":["忆昔曾随计吏行，浮湛州县竟何成。","凉风袅袅仙舟去，夕日依依魏阙情。","金匮故藏多钜典，石渠高论尽鸿生。","栖身朱墨非君事，早晚公车上姓名。"]},{"t":"送沙彦文架阁分题得西山","f":"七言律诗","c":["忆昔寒江破浪归，西山回首落烟霏。","忍逢朝士登舟去，如望仙人拔宅飞。","游戏何妨依绿水，追趋早已到黄扉。","公馀若过滕王阁，为捲朱帘挹翠微。"]},{"t":"寄题高远楼","f":"七言律诗","c":["闻道危楼架泬寥，楼前物色不萧条。","窗临谢傅祠边树，门对曹娥渡口潮。","解使诗人争应接，也知老子极风标。","倦游已忘山阴路，胜饯仍须折简招。"]},{"t":"题东柯谷图","f":"七言律诗","c":["长松密竹翠交加，洞府新开碧海涯。","石上仙人留足迹，春深涧水出桃花。","流传图画来千里，生长儿孙只一家。","目断飞鸿那可到，旧游空指赤城霞。"]},{"t":"闻赵继清调安陆县尹","f":"七言律诗","c":["慈恩塔上墨犹鲜，一别重来十七年。","相见都门惊判袂，又闻泽国去鸣弦。","素衣久出风尘外，青琐行依雨露边。","跂马望君先数日，县花虽好莫留连。"]},{"t":"送毕县尹","f":"七言律诗","c":["归途环佩晓珊珊，白日青天映羽翰。","疑是省亲辞太学，惊闻出宰用郎官。","花迎墨绶春光暮，风引仙舟海色寒。","想见捧觞仍綵戏，乡人争作锦衣看。"]},{"t":"次韵题刘氏石壁精舍","f":"七言律诗","c":["佳城杳杳隔千峰，精舍寥寥一径通。","夜静寒泉犹映月，秋深老树不惊风。","旧题尚喜苔碑在，高卧无令蕙帐空。","我已倦游今白发，有山如此愿长终。"]},{"t":"和外舅主簿公自为挽诗","f":"七言律诗","c":["五十年前马上飞，青春如水去难追。","一从玉树歌残后，数到黄粱梦觉时。","李贺元无楼可记，刘伶漫有锸相随。","少须海上蟠桃熟，归簉仙班恐未迟。"]},{"t":"留别一公琳公","f":"七言律诗","c":["浪走红尘鬓已丝，此身端合老岩扉。","兴来复举山阴棹，别去仍留海上衣。","夜听泉声如雨落，晴看天末有云归。","浮萍飞絮何时定，空使诗人赋式微。"]},{"t":"送傅汝砺之安南","f":"七言律诗","c":["南徼车书路不遥，秋风使节下青霄。","颇闻僚佐登才彦，应有文章达教条。","日照楼船江水活，天低铜柱瘴云消。","归时岭上梅花发，想见诗囊未寂寥。"]},{"t":"送式公归高丽","f":"七言律诗","c":["一锡凌空海上飞，星河荡漾宿云披。","颇惊辽鹤归来晚，正值骊龙睡觉时。","百尺珊瑚无地种，六花薝卜任风吹。","高秋兰若烟波外，此乐应须久自知。"]},{"t":"题宁节妇诗卷","f":"七言律诗","c":["春旗柳色映门闾，华扁新题节妇居。","作传小裁青竹简，疏封近降紫泥书。","河壖松柏风烟外，阶戺芝兰雨露初。","三釜及亲殊未晚，花前何日奉安舆。"]},{"t":"送孔御史归曲阜","f":"七言律诗","c":["清流共喜聚群贤，新渥时闻下九天。","东观紬书何日了，中丞遗笏要人传。","过家莫久依林庙，封事先须彻御筵。","千载斯文寄来哲，临分握手重悬悬。"]},{"t":"送谢仲连小鹿巡检","f":"七言律诗","c":["而翁许史旧家声，遗子黄金不满籯。","坐拥斋炉惊岁晏，出乘边障属时清。","游山定复多新句，饮酒何妨得老兵。","愧我白头官尚冷，夜深仍对读书檠。"]},{"t":"送乌编修代祀海岳南镇兼简明善隐君","f":"七言律诗","c":["承明退直马如龙，将指祠庭礼数崇。","岳色非烟生近甸，川灵藏器出幽宫。","周原共识皇华使，禹穴谁陪太史公。","亦见安阳韩处士，为言客鬓已秋蓬。"]},{"t":"题张武定公死事诗卷后","f":"七言律诗","c":["古称马革裹尸还，祗有空言世共传。","一死如公良伟甚，百年遗庙独巍然。","要从身后观馀烈，试听军中奏凯还。","文武衣冠方迭起，后先奕叶更绵绵。"]},{"t":"题王君冕同年芳润亭","f":"七言律诗","c":["花县归来昼寂寥，终南山翠涌亭皋。","林深未觉兰荪变，天远何妨雨露高。","此去溉根须食实，谁分剩馥与残膏。","行看小试挥毫手，香雾霏霏滴凤毛。"]},{"t":"题丁文苑同年哀词后","f":"七言律诗","c":["自别琼林雨露边，江湖目断绣衣前。","禹门尚想龙初化，辽海惊闻鹤已仙。","烈日秋霜空耿耿，重山宿草正芊芊。","不才后死知何用，坐对诸郎独泫然。"]},{"t":"送尉彦诚道州经历","f":"七言律诗","c":["一别垂垂四十年，朔风吹鬓两苍然。","寒毡久坐归何日，上幕初登望若仙。","莫使催科书下考，盛谈名理继前贤。","春生马首逢回雁，并写相思入近篇。"]},{"t":"送陈君归江西","f":"七言律诗","c":["咫尺清光近玉除，姓名何不达公车。","也知贾傅今无策，犹幸虞卿旧有书。","江上归帆随去雁，年来旅食厌骑驴。","诸公正索山人价，能勿相招学隐居。"]},{"t":"次韵苏侍郎平村暮归","f":"七言律诗","c":["中台多暇独仪曹，退食归来路不遥。","扶老未须苍玉杖，行春聊过赤阑桥。","挥毫风雨倾三峡，听履星辰接九霄。","愧我白头方倚席，敢将巴曲和仙韶。"]},{"t":"送尚子正理问","f":"七言律诗","c":["上相分临控列州，理官高选用儒流。","风生使节声华旧，地近台垣宠数优。","南土政平多暇日，西山气爽入新秋。","公馀若过滕王阁，烦为题诗在上头。"]},{"t":"送苏伯修宪使","f":"七言律诗","c":["久参法从侍凝旒，忽拥幨轺按列州。","太史山川皆熟路，淮南草木自生秋。","遥瞻龙节辞中禁，尚想鳌峰接俊游。","樗散郑虔无所用，幸搜岩壑副旁求。"]},{"t":"送王止善检挍","f":"七言律诗","c":["官无失政吏无私，钩挍宁烦事细微。","遥想名曹多暇日，不妨高咏发清晖。","潮生江上仙舟迥，春到湖边驿使稀。","送尽北来南去客，石田茅屋几时归。"]},{"t":"送高唐李知州","f":"七言律诗","c":["来登延阁预时髦，出守名州领教条。","已羡汉儒知吏事，要观齐俗变风谣。","双旌前路方迢递，八座家声未寂寥。","此去行须归报政，鸣珂几日造昕朝。"]},{"t":"送傅汝砺广州教授","f":"七言律诗","c":["耻学山人赴辟书，勇随使者驾轺车。","横经久合居高座，上冢应须过旧庐。","黑夜文星南斗外，青冥鹏路北风初。","来期莫落梅花后，待诏先生席正虚。"]},{"t":"送刘遂初修撰","f":"七言律诗","c":["近闻退直自承明，忽报扬镳出凤城。","未老已嫌金带重，暂归不著绣衣行。","故人尚作瀛州客，岁晚无忘魏阙情。","临别赠言聊复尔，谁能持酒劝公荣。"]},{"t":"送于指挥归密州","f":"七言律诗","c":["故山东望路何长，远奉灵輀返寿藏。","予告公朝存旧典，疏封泉壤发幽光。","总戎行复开油幕，儤直仍须赴玉堂。","它日过家如上冢，岁寒松柏正苍苍。"]},{"t":"书巢张君挽章","f":"七言律诗","c":["岁晚巢居寄一枝，上林无树可相依。","不随叶县飞凫去，竟作辽东化鹤归。","架上牙签书在否，门前珠履客来稀。","春江如箭船如马，忍见舟旗飏落晖。"]},{"t":"次韵伯雨腊月八日雪中同登来鹤亭","f":"七言律诗","c":["兴来欲泛山阴雪，不奈舟胶野水凝。","朝士白头愁独步，仙人赤脚傲层冰。","招来尽是鸡群鹤，趍附空惭骥尾蝇。","夜久松龛同拥毳，绝胜儤值有青绫。"]},{"t":"至大庚戌正月二十一日予与儒公禅师谒松瀑真人于龙翔上方翰林邓先生适至予为赋诗四韵诸老皆属和焉后三十一年是为至元辛已正月二十三日过伯雨尊师之贞居无外式公刘君衍卿不期而集辄追用前韵以纪一时之高会云","f":"七言律诗","c":["庐山旧事谁能继，三十年前此会同。","偶尔共来今日雨，萧然犹有古人风。","坐深遥对花如雾，兴尽徐归月在空。","仰止前修那堪作，聊追馀响托无穷。"]},{"t":"送史景福","f":"七言律诗","c":["十年相望各天涯，上幕新开鬓未华。","日出公庭来雁鹜，风生老笔动龙蛇。","蜀乡路远春多雨，江国云深树有花。","若见君家彭泽令，为言且莫问桑麻。"]},{"t":"府判谢公挽章","f":"七言律诗","c":["换得朝衣不称身，勇辞新爵号遗民。","鍊成偃月炉中药，阅遍铜驼陌上人。","鲁国灵光俄委地，谢家玉树正伤春。","忽闻旧唱贞元曲，衰涕能无洒石麟。"]},{"t":"六月十二日上京翰林开院喜雨院长开府公俾为诗以志之","f":"七言律诗","c":["雨浥鳌峰长绿苔，佳辰良会玉堂开。","凉生薰殿宸居近，恩予官壶诏使来。","尽醉不愁骑马滑，新诗可待片云催。","作霖正尔须公等，行见文星入上台。"]},{"t":"安南遣使入朝用故事奉贽纳谒于翰林其归也上介黎括以赠言为请赋诗四韵以遗之","f":"七言律诗","c":["上圣敷文格远人，外藩修职用儒臣。","并驰使介踰丹徼，特设朝班觐紫宸。","炎海计程归路永，都亭燕饯宠光新。","祗承德意勤宣布，鼓舞鸢鱼咏至仁。"]},{"t":"送徐志尹赴安乡县尹","f":"七言律诗","c":["自为从史直銮坡，几见乡山烂斧柯。","能事正宜参笔削，借才聊复试弦歌。","屈原故国兰都长，陶令公田秫最多。","应笑衰翁苦留滞，汗青无日欲如何。"]},{"t":"送陈元达代祠补怛洛迦山","f":"七言律诗","c":["天下名山小白花，鲸波帖帖度仙槎。","函香秘宇祈灵贶，出节宸廷振使华。","殿榜旧誇韦诞笔，锦衣重过买臣家。","相门乔木殊无恙，万古清风碧海涯。"]},{"t":"次韵答胡古愚博士","f":"七言律诗","c":["麻衣草坐老仙翁，曾及清时侈际逢。","行殿晓趋开豹尾，禁林秋宴出驼峰。","休官尚想英游并，爱客何嫌异味重。","况乃东阳山水窟，主张风月有诗宗。"]},{"t":"送李师曾蒋仲善赴春官","f":"七言律诗","c":["忆随飞鹗上秋天，梦断慈恩四十年。","及此鬓毛俱秃尽，见君头角共崭然。","计偕已趣轺车动，胪句行听卫士传。","紫陌红尘衣易化，看花得意莫留连。"]},{"t":"哭御史王公 其一","f":"七言绝句","c":["有人新自甬东来，别后音书第一回。","欲问布帆无恙否，岂知尘世隔蓬莱。"]},{"t":"哭御史王公 其二","f":"七言绝句","c":["被发胡为竟渡河，由来魑魅喜人过。","不须待听山阳笛，一曲箜篌哀思多。"]},{"t":"哭御史王公 其三","f":"七言绝句","c":["早岁栖身拟凤池，桑田为海已多时。","路人方为乘骢止，流水生涯遽可悲。"]},{"t":"哭御史王公 其四","f":"七言绝句","c":["玉堂政要谪仙人，何意先成采石坟。","人物渺然时事异，漫今平地有青云。"]},{"t":"哭御史王公 其五","f":"七言绝句","c":["金阜原头草未生，儿郎俄已去骑鲸。","黄泉会有相逢处，转见人间母子情。"]},{"t":"哭御史王公 其八","f":"七言绝句","c":["孤儿思父母怜儿，忍见铭旌独返时。","毕竟江鱼与蝼蚁，世间何物最堪悲。"]},{"t":"哭御史王公 其九","f":"七言绝句","c":["楚客犹疑刻剑痕，秋风已到孟尝门。","残潮落月天涯夜，剪纸谁招万里魂。"]},{"t":"哭御史王公 其十","f":"七言绝句","c":["天吴罔象正纵横，谁认鳌山顶上行。","海气昏昏风雨恶，梦中无路吊先生。"]},{"t":"避暑图","f":"七言绝句","c":["一丘一壑古遗民，十里清风不属人。","閒对青山挥白羽，世间何物是红尘。"]},{"t":"围棋图","f":"七言绝句","c":["有客围棋洞口归，天荒地老已多时。","人言此客殊痴绝，画里看棋我更痴。"]},{"t":"次韵章兄雨中 其一","f":"七言绝句","c":["卧听风水共喧喧，起视青空白雨悬。","秪谓桑田可无恙，不知江势欲吞天。"]},{"t":"次韵章兄雨中 其二","f":"七言绝句","c":["茫茫平陆一尺水，瑟瑟凉飙五月秋。","莫谓天公无皂白，误将阴雨怨鸣鸠。"]},{"t":"次韵章兄雨中 其三","f":"七言绝句","c":["故山回首杜鹃啼，客舍谁怜寄一枝。","赖有四门章博士，不缘风雨废谈诗。"]},{"t":"次韵章兄雨中 其五","f":"七言绝句","c":["草长故山怀独往，苔生今雨叹离居。","谁能共饮桃源酒，一醉千年不愿馀。"]},{"t":"偈二首 其一","f":"七言绝句","c":["久谓声闻难作佛，今知龙女解成男。","分明信有旁人分，五十三身第一参。"]},{"t":"偈二首 其二","f":"七言绝句","c":["息心无想成无记，有见还同有相存。","不尽普贤殊胜行，随方愿启一城门。"]},{"t":"松江舟中偶书 其一","f":"七言绝句","c":["山房偶为故人留，又领飞云过别州。","白浪千花帆一叶，茫茫天地此生浮。"]},{"t":"滦阳邢君隐于药市制芍药芽代茗饮号曰琼芽先朝尝以进御云 其一","f":"七言绝句","c":["君家药笼有新储，苦口时供茗饮须。","一味醍醐充佐使，从今合唤酪为奴。"]},{"t":"题李早画马","f":"七言绝句","c":["平沙如雪草如烟，想见春风士马閒。","玉勒锦鞯尘土化，画图流落尚人间。"]},{"t":"石节妇诗","f":"七言绝句","c":["伯也南征去不归，舅姑长恸小儿悲。","元戎奏彻铙歌曲，来听完州节妇诗。"]},{"t":"送许参政归武昌别业 其一","f":"七言绝句","c":["九衢荡荡绿槐风，旌旆摇摇马首东。","惆怅凤凰池上客，青天万里一冥鸿。"]},{"t":"送许参政归武昌别业 其二","f":"七言绝句","c":["待漏东华霜满靴，挂冠神武意如何。","也知久历中书考，若比汾阳恐未多。"]},{"t":"送许参政归武昌别业 其三","f":"七言绝句","c":["毡笔书题墨尚新，杏花零落故园春。","一从今日公归后，身到黄扉复几人。"]},{"t":"送许参政归武昌别业 其四","f":"七言绝句","c":["晓日都门祖帐开，路人啧啧叹贤哉。","东风无限新桃李，不敢烦公手自栽。"]},{"t":"送许参政归武昌别业 其五","f":"七言绝句","c":["片云为雨出山时，群物欣欣各自私。","收敛神功去无迹，寻常草木竟何知。"]},{"t":"送许参政归武昌别业 其六","f":"七言绝句","c":["住近韩家昼锦堂，不将牙纛诧同乡。","翻嫌相国归来日，腰下犹悬太守章。"]},{"t":"送许参政归武昌别业 其七","f":"七言绝句","c":["白袍鹄立漫纷纷，遥听车音共候门。","相见唯须饮醇酒，看山看水坐忘言。"]},{"t":"送许参政归武昌别业 其八","f":"七言绝句","c":["南游聊食武昌鱼，莫学骚人赋卜居。","天子若思真汉相，可云吾亦爱吾庐。"]},{"t":"送许参政归武昌别业 其九","f":"七言绝句","c":["五十人间富贵年，山中道士早求仙。","石田茅屋归无计，愁绝灯前老郑虔。"]},{"t":"送许参政归武昌别业 其十","f":"七言绝句","c":["龙门尚想旧同游，药笼深惭晚见收。","新筑沙堤却何日，欲归且复为公留。"]},{"t":"饮后示陈生","f":"七言绝句","c":["岁终博士不超迁，便腹先生醉欲眠。","匡鼎若来犹自可，后堂无处著彭宣。"]},{"t":"题洪崖出游图","f":"七言绝句","c":["灵仙飞化事难言，驴背春风度市门。","不到人间今已久，多应醉卧古藤根。"]},{"t":"赠写真","f":"七言绝句","c":["自是清时翰墨流，水边林下莫淹留。","汉皇正在麒麟阁，欲画将军博陆侯。"]},{"t":"送傅梅溪迁任福州","f":"七言绝句","c":["往岁从君直禁林，相于道义最情深。","公车承诏庄行日，莫怪频频酒屡斟。"]},{"t":"题王南谷大夫自作墨梅诗送傅君时教授南归","f":"七言绝句","c":["何逊扬州迹未陈，染衣不是洛城尘。","毫端一线阳和力，中有江南万斛春。"]},{"t":"题宣和御画","f":"七言绝句","c":["青城尘土昼濛濛，百二山河一夕空。","收敛神功归化笔，野花啼鸟尚春风。"]},{"t":"题陆山长柳州","f":"七言绝句","c":["簇簇春山紫翠围，瀰瀰烟水白鸥飞。","东被正作西湖长，一曲空惭贺监归。"]},{"t":"题清镜阁","f":"七言绝句","c":["投老归来贺监船，何时结屋镜湖边。","羡公高坐毗卢阁，万水同波一月圆。"]},{"t":"题赵伯容鹤巢","f":"七言绝句","c":["平原公子去翩翩，独溯刚风直上天。","家近孤山春树好，归期莫落后千年。"]},{"t":"次韵答济公 其一","f":"七言绝句","c":["旧游零落如星散，坐对孤山似守株。","听彻贞元供奉曲，羞将短发照西湖。"]},{"t":"次韵答济公 其二","f":"七言绝句","c":["病须药饵亲丹灶，老厌书帷彻绛纱。","幸有文殊来见问，更无天女散天花。"]},{"t":"次韵答济公 其三","f":"七言绝句","c":["白头朝士方徒步，欲过六桥愁路赊。","目断红云花鸟上，楼居缥缈梵王家。"]},{"t":"桃源图","f":"七言绝句","c":["山容惨惨将为雨，云气垂垂欲傍花。","莫问前村何处觅，垂萝盘石即吾家。"]},{"t":"次韵题墨梅","f":"七言绝句","c":["一自携家湖水东，放舟时度玉花丛。","因君貌得横斜影，闲却孤山月一篷。"]},{"t":"题先照楼","f":"七言绝句","c":["初日团团出海东，凌晨先照最高峰。","不知今日华严界，楼阁新开第几重。"]},{"t":"武王扇暍图","f":"七言绝句","c":["一夫偶尔获清凉，四海仁风孰奉扬。","有道曾孙不忘远，幸均此施遍群方。"]},{"t":"题平章康里公春日杏园西即事诗后","f":"七言绝句","c":["锵金戛玉音声古，抉石奔泉气势雄。","目断云车天路永，小楼春雨杏花风。"]},{"t":"题明公画兰","f":"七言绝句","c":["吴僧戏笔点生绡，袅袅幽花欲动摇。","梦断楚江烟雨外，秋风滦水暮潇潇。"]},{"t":"壬辰春三月游左溪癸巳春三月游天宫有感而赋","f":"七言绝句","c":["频年谒拜祖师庭，祗有山光与水声。","尚想玄珠密相付，免令我漫肆讥评。"]},{"t":"讼魃","f":"楚辞体","c":["皇亶正直兮冒下惟仁。","肇毓嘉种兮诞生烝人。","胡汝魃之暴亢兮盗威柄以自神。","祸凶是司兮俾阏厥伸。","穷千里以逞毒兮岂此土为匪民。","岁丁未而孕孽兮俶九厄之遘凶。","乘阳窃出兮霍霍隆隆。","斥弃舆马兮谓肥?其犹龙。","绛㠾彤靷兮疾走如风。","扬氛壒于浍涂兮瞻我野其童童。","糇粮殚于草木兮搏块砾之不可食。","旄倪僵尸兮强敚死力。","首丘而弗遑兮胡悯隶之可得。","狐狸饱而跳踉兮腐胔纵横。","藜藿出户兮室无哭声。","野蓁蓁其谁辟兮磷火煜其宵行。","皇保下人兮曷椓丧而极斯。","乐人之死兮职魃所为。","耗贼大和兮遏玄泽于既施。","朋殃友厉兮出入敖娭。","仰九关而往愬兮予踆踆其屡止。","曰无往而勿复兮其悔祸之汝俟。","胡披猖而荐肆兮将穷菑乎今兹。","扇虐燄于荧荧兮导伯强使先之。","怒气㶿其如饙兮憯薄人之四肢。","挺刃歘至兮狼顾睽睽。","曾遗民其几何兮矧有秋以为期。","咨汝魃兮诚忮忍而险愎。","凭妖矜孽兮畔戾圣则。","谓吾莫汝烛兮何裸身顶目而辟易。","有赫临汝兮顾微臣其何力。","命不可久斁兮威不可久乘。","孰怙终而稔毒兮能自逭于天刑。","皇斯震怒兮叱咤雷霆。","斧钺孔利兮百神效灵。","害戕屏绝兮鬯嘉生于百龄。","磔弃妖膂兮沈溺清泠。","嗟魃弗悛兮后虽悔其何惩。"]}]};